import { useEffect, useState, type FormEvent, type MouseEvent } from 'react'
import { Link, useLocation, useNavigate, useParams } from 'react-router'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { hubApi } from './api'

type Page<T> = { items: T[]; nextCursor: string | null; hasMore: boolean }
type Connection = { id: string; publicId: string; platformCode: string; environment: string; displayName: string; externalStoreId: string; status: string; apiVersion: string; lastTestedAt: string | null; lastSuccessAt: string | null; lastErrorCode: string | null; hasCredential: boolean; version: number }
type Capability = { code: string; supportLevel: string; sourceUrl: string | null; verifiedAt: string | null; constraintsJson: string | null; version: number }
type OrderLine = { id: string; sku: string; barcode: string | null; title: string; orderedQuantity: number; cancelledQuantity: number; shippedQuantity: number; deliveredQuantity: number; returnedQuantity: number; unitPrice: number; vatRate: number; rawStatus: string; variantId: string | null; modelCode: string | null; optionSignature: string | null; imageUrl: string | null }
type Order = { id: string; orderNumber: string; derivedStatus: string; currency: string; grossAmount: number; discountAmount: number; netAmount: number; orderedAt: string; lineCount: number; packageCount: number; version: number; connectionId: string | null; platformCode: string; platformDisplayName: string; customerName: string; customerEmail: string | null; customerTaxOrIdentityNumber: string | null; orderType: string; isMicroExport: boolean; shipmentAddressJson: string; invoiceAddressJson: string; shipmentDueAt: string | null; isDeadlineCritical: boolean; invoiceStatus: string; invoiceId: string | null; invoiceDocumentUrl: string | null; cargoProviderName: string | null; cargoTrackingNumber: string | null; primaryImageUrl: string | null; productQuantity: number; lines: OrderLine[] | null; packages: Shipment[] | null }
type OrderFilters = { search: string; status: string; platform: string; listing: string; cargo: string; invoice: string; dateFrom: string; dateTo: string }
const initialOrderFilters: OrderFilters = { search: '', status: 'ALL', platform: 'ALL', listing: 'ALL', cargo: 'ALL', invoice: 'ALL', dateFrom: '', dateTo: '' }
type OrderDetail = { id: string; orderNumber: string; derivedStatus: string; currency: string; grossAmount: number; discountAmount: number; netAmount: number; orderedAt: string; connectionId: string | null; platformCode: string; platformDisplayName: string; customerName: string; customerEmail: string | null; customerPhone: string | null; customerTaxOrIdentityNumber: string | null; orderType: string; isMicroExport: boolean; isEInvoiceAvailable: boolean | null; shipmentAddressJson: string; invoiceAddressJson: string; shipmentDueAt: string | null; invoiceStatus: string; invoiceDocumentUrl: string | null; lines: OrderLine[]; packages: Shipment[]; version: number }
type CreatedInvoice = { id: string }
type Shipment = { id: string; orderId: string; orderNumber: string; externalPackageId: string; status: string; rawStatus: string; cargoTrackingNumber: string | null; cargoProviderName: string | null; statusOccurredAt: string; version: number }
type ShipmentDetail = { package: Shipment; allowedActions: string[]; supportedLabelFormats: string[]; documents: Array<{ id: string; documentKind: string; format: string; source: string; documentVersion: number; createdAt: string; expiresAt: string | null }> }
type ReturnClaim = { id: string; externalClaimId: string; orderNumber: string; status: string; rawStatus: string; reasonText: string | null; actionDueAt: string | null; version: number; customerName: string; orderedAt: string | null; orderAmount: number; currency: string; cargoProviderName: string | null; cargoTrackingNumber: string | null; primaryImageUrl: string | null; productCount: number }
type ReturnLine = { id: string; externalLineId: string; orderLineId: string; sku: string; barcode: string | null; title: string; quantity: number; disposedQuantity: number; remainingQuantity: number; unitPrice: number; imageUrl: string | null; hasInventoryMapping: boolean }; type ReturnDetail = ReturnClaim & { reasonCode: string | null; allowedActions: string[]; lines: ReturnLine[] | null; stockDispositionAvailable: boolean }; type ReturnIssueReason = { id: string; name: string; evidenceRequired: boolean }
type LocalCategory = { id: string; name: string; path: string; depth: number; isLeaf: boolean; isActive: boolean; version: number }
type LocalBrand = { id: string; name: string; isActive: boolean; version: number }
type LocalAttribute = { id: string; code: string; name: string; dataType: string; isActive: boolean; version: number; values: { id: string; value: string; isActive: boolean }[] }
type CategoryRequirementView = { attributeId: string; isRequired: boolean; allowsCustomValue: boolean; displayOrder: number; attribute: LocalAttribute }
type ReferenceItem = { externalId: string; parentExternalId: string | null; name: string; path: string; depth: number; isLeaf: boolean; isActive: boolean; isRequired: boolean | null; allowsCustomValue: boolean | null; allowsMultipleValues: boolean | null }
type ReferenceData = { snapshotId: string; resourceType: string; fetchedAt: string; items: ReferenceItem[] }
type CatalogMapping = { id: string; connectionId: string; snapshotId: string; localId: string; scopeExternalId: string; externalId: string; status: string; verifiedAt: string | null; version: number }

function idempotency() { return crypto.randomUUID() }
function ErrorBox({ error }: { error: unknown }) { return <div role="alert" className="error">{error instanceof Error ? error.message : 'İşlem tamamlanamadı.'}</div> }
function Busy({ text = 'Veriler yükleniyor…' }: { text?: string }) { return <div className="status inline" role="status"><div className="spinner" /><strong>{text}</strong></div> }
function Empty({ children }: { children: string }) { return <div className="empty"><strong>Kayıt yok</strong><p>{children}</p></div> }
function Badge({ value }: { value: string }) { const tone = value === 'SUPPORTED' || value === 'ACTIVE' || value === 'DELIVERED' || value === 'APPROVED' ? 'good' : value === 'UNKNOWN' || value === 'DRAFT' || value === 'VERIFIED' ? 'warn' : 'neutral'; return <span className={`badge ${tone}`}>{value}</span> }
function DateText({ value }: { value: string | null }) { return <>{value ? new Date(value).toLocaleString('tr-TR') : '—'}</> }

function remainingText(value: string | null) { if (!value) return 'Termin bilgisi gelmedi'; const ms = new Date(value).getTime() - Date.now(); if (ms <= 0) return 'Süre doldu'; const hours = Math.ceil(ms / 3_600_000); return hours < 48 ? `${hours} saat kaldı` : `${Math.ceil(hours / 24)} gün kaldı` }
function orderTypeLabel(value: string) { return value === 'MIKRO_IHRACAT' ? 'Mikro ihracat' : value === 'KURUMSAL' ? 'Kurumsal' : 'Bireysel' }
function safeJson(value: string) { try { return JSON.parse(value || '{}') as Record<string, unknown> } catch { return {} } }
function addressText(value: string) { const source = safeJson(value); const data = [source.shipmentAddress, source.invoiceAddress, source.address].find(item => item && typeof item === 'object') as Record<string, unknown> | undefined ?? source; const parts = ['fullAddress', 'address1', 'address2', 'district', 'city', 'countryCode', 'postalCode'].map(key => data[key]).filter(item => typeof item === 'string' && item.trim()); return parts.length ? parts.join(' · ') : 'Adres bilgisi gelmedi' }
function optionRows(value: string | null) { const parts = (value ?? '').split(/[|,·;]+/).map(item => item.trim()).filter(Boolean); const fields = parts.map(part => { const match = part.match(/^([^:=-]+)\s*[:=-]\s*(.+)$/); return match ? { label: match[1].trim(), value: match[2].trim() } : null }).filter((item): item is { label: string; value: string } => item !== null); return fields.length ? fields : value ? [{ label: 'Seçenek', value }] : [] }
function longDate(value: string) { return new Intl.DateTimeFormat('tr-TR', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) }
function deliveryText(item: Order) { const shipment = item.packages?.[0]; if (item.derivedStatus === 'CANCELLED') return { label: 'İptal tarihi', value: shipment?.statusOccurredAt ? longDate(shipment.statusOccurredAt) : 'İptal zamanı bekleniyor', note: null, overdue: false }; if (item.derivedStatus === 'DELIVERED') return { label: 'Teslim edildi', value: shipment?.statusOccurredAt ? longDate(shipment.statusOccurredAt) : 'Teslimat zamanı bekleniyor', note: null, overdue: false }; if (item.derivedStatus === 'SHIPPED') return { label: 'Taşıma durumunda', value: shipment?.statusOccurredAt ? longDate(shipment.statusOccurredAt) : 'Kargo zamanı bekleniyor', note: 'Bugün kargoya verildi', overdue: false }; const due = item.shipmentDueAt ? new Date(item.shipmentDueAt).getTime() : Number.NaN; const overdueDays = Number.isFinite(due) ? Math.floor((Date.now() - due) / 86_400_000) : 0; if (overdueDays > 0) return { label: '', value: `Siparişiniz ${overdueDays} gün gecikmiştir!`, note: 'Siparişinizi en kısa sürede kargoya teslim etmelisiniz.', overdue: true }; return { label: 'Kalan süre', value: item.shipmentDueAt ? remainingText(item.shipmentDueAt) : item.isMicroExport ? 'Trendyol termin bilgisi göndermedi' : 'Termin zamanı bekleniyor', note: null, overdue: false } }
function OrderQuickDetails({ orderId }: { orderId: string }) {
  const [open, setOpen] = useState(false)
  const query = useQuery({ queryKey: ['order-quick-detail', orderId], queryFn: () => hubApi<OrderDetail>(`/orders/${orderId}`), enabled: open })
  const item = query.data
  return <details className="operation-details order-expanded" onToggle={event => setOpen(event.currentTarget.open)}>
    <summary><span>Sipariş detaylarını göster</span><small>Müşteri, adres, ürün, ödeme ve kargo</small></summary>
    {query.isLoading ? <Busy text="Sipariş detayları yükleniyor…" /> : query.isError ? <ErrorBox error={query.error} /> : item ? <div className="order-expanded-content">
      <section className="order-detail-section customer-section"><div className="section-heading"><span className="section-icon">01</span><div><h3>Müşteri ve sipariş</h3><p>Alıcı kimliği ve sipariş özeti</p></div></div><dl className="detail-facts"><div><dt>Müşteri</dt><dd>{item.customerName}</dd></div><div><dt>E-posta</dt><dd>{item.customerEmail ?? 'Belirtilmedi'}</dd></div><div><dt>TC / Vergi no</dt><dd>{item.customerTaxOrIdentityNumber ?? 'Belirtilmedi'}</dd></div><div><dt>Sipariş tipi</dt><dd>{orderTypeLabel(item.orderType)}</dd></div><div><dt>Sipariş tarihi</dt><dd><DateText value={item.orderedAt} /></dd></div><div><dt>Platform</dt><dd>{item.platformDisplayName}</dd></div></dl></section>
      <section className="order-detail-section address-section"><div className="section-heading"><span className="section-icon">02</span><div><h3>Adresler</h3><p>Teslimat ve fatura bilgileri</p></div></div><div className="address-cards"><article><small>Teslimat adresi</small><strong>{item.customerName}</strong><p>{addressText(item.shipmentAddressJson)}</p></article><article><small>Fatura adresi</small><strong>{item.customerName}</strong><p>{addressText(item.invoiceAddressJson)}</p></article></div></section>
      <section className="order-detail-section lines-section"><div className="section-heading"><span className="section-icon">03</span><div><h3>Ürünler</h3><p>{item.lines.length} sipariş satırı</p></div></div><div className="order-line-list">{item.lines.map(line => <article key={line.id}>{line.imageUrl ? <img src={line.imageUrl} alt="" /> : <span className="line-image-placeholder">▧</span>}<div><strong>{line.title}</strong><small>SKU: {line.sku} · Barkod: {line.barcode ?? '—'}</small><small>{line.optionSignature || line.modelCode || 'Standart ürün'}</small></div><div><small>Adet</small><strong>{line.orderedQuantity}</strong></div><div><small>Birim fiyat</small><strong>{line.unitPrice.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</strong></div><Badge value={line.rawStatus} /></article>)}</div></section>
      <section className="order-detail-section finance-section"><div className="section-heading"><span className="section-icon">04</span><div><h3>Tutar ve teslimat</h3><p>Finansal özet ve paket bilgileri</p></div></div><div className="finance-delivery-grid"><dl className="amount-summary"><div><dt>Brüt tutar</dt><dd>{item.grossAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</dd></div><div><dt>İndirim</dt><dd>− {item.discountAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</dd></div><div className="total"><dt>Net tutar</dt><dd>{item.netAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</dd></div></dl><div className="package-list">{item.packages.length ? item.packages.map(pack => <article key={pack.id}><div><small>Kargo</small><strong>{pack.cargoProviderName ?? 'Henüz atanmadı'}</strong></div><div><small>Takip numarası</small><strong>{pack.cargoTrackingNumber ?? 'Bekleniyor'}</strong></div><Badge value={pack.status} /></article>) : <div className="empty compact-empty"><strong>Paket bekleniyor</strong><p>Sipariş için henüz kargo paketi oluşmadı.</p></div>}</div></div></section>
      <div className="order-expanded-footer"><span><Badge value={item.derivedStatus} /> Fatura: {item.invoiceStatus}</span><Link className="button-link" to={`/orders/${item.id}`}>Tam sipariş sayfasını aç →</Link></div>
    </div> : null}
  </details>
}
function InvoiceInfoModal({ item, onClose }: { item: Order; onClose: () => void }) {
  const detail = useQuery({ queryKey: ['invoice-info-order', item.id], queryFn: () => hubApi<OrderDetail>(`/orders/${item.id}`) })
  const order = detail.data
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal invoice-info-modal" role="dialog" aria-modal="true" aria-labelledby="invoice-info-title" onMouseDown={event => event.stopPropagation()}><header><h2 id="invoice-info-title">Fatura &amp; Adres Bilgileri</h2><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header>{detail.isLoading ? <Busy text="Fatura ve adres bilgileri API’den yükleniyor…" /> : detail.isError || !order ? <ErrorBox error={detail.error} /> : <><div className="invoice-address-sheet"><section><h3>Teslimat Adresi</h3><dl><dt>Ad-soyad:</dt><dd>{order.customerName}</dd><dt>Adres:</dt><dd>{addressText(order.shipmentAddressJson)}</dd></dl></section><section><h3>Fatura Adresi</h3><dl><dt>Ad-soyad:</dt><dd>{order.customerName}</dd><dt>Adres:</dt><dd>{addressText(order.invoiceAddressJson)}</dd><dt>E-Fatura Mükellefi:</dt><dd>{order.isEInvoiceAvailable === null ? 'Bilgi gelmedi' : order.isEInvoiceAvailable ? 'Evet' : 'Hayır'}</dd></dl></section><section className="invoice-contact"><dl><dt>E-posta Adresi:</dt><dd>{order.customerEmail ?? 'Bilgi gelmedi'}</dd><dt>Telefon Numarası:</dt><dd>{order.customerPhone ?? 'Bilgi gelmedi'}</dd></dl></section><p>Faturanızı <strong>Fatura işlemleri</strong> altındaki <strong>Fatura Yükle</strong> alanına PDF, JPEG, JPG veya PNG biçiminde ekleyebilirsiniz. Entegratörle çalışıyorsanız fatura bağlantısını bu alandan takip edebilirsiniz.</p></div><footer><button type="button" className="secondary" onClick={onClose}>Vazgeç</button><button type="button" onClick={() => window.print()}>Yazdır</button></footer></>}</section></div>
}

function CourierChangeModal({ item, onClose }: { item: Order; onClose: () => void }) {
  const carriers = ['Yurtiçi Kargo', 'Sürat Kargo', 'DHL eCommerce', 'PTT Kargo', 'Kolay Gelsin', 'Aras Kargo', 'Horoz Kargo', 'CEVA Logistics']
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal courier-change-modal" role="dialog" aria-modal="true" aria-labelledby="courier-change-title" onMouseDown={event => event.stopPropagation()}><header><div><h2 id="courier-change-title">Paketi hangi firma ile göndermek istiyorsunuz?</h2><p>Seçilen kargo firması için fiyat ve uygunluk bilgisi, işlem açılmadan önce doğrulanır.</p></div><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header><p className="courier-description"><strong>#{item.orderNumber}</strong> numaralı paket için kargo firması değişikliği şu anda yalnız ön izleme modunda gösterilir; hiçbir dış işlem başlatılmaz.</p><h3>Standart Kargo Firmaları <span>(0–30 desi)</span></h3><div className="courier-options">{carriers.map(carrier => <label key={carrier}><input type="radio" name="courier" disabled /><span>{carrier}</span></label>)}</div><footer><button type="button" className="secondary" onClick={onClose}>Vazgeç</button><button type="button" disabled>İşlemi Yap</button></footer></section></div>
}

function OrderReferenceRow({ item, selected, onSelect, openMenu, onMenuChange, onInvoiceDetails, onCourierChange }: { item: Order; selected: boolean; onSelect: (checked: boolean) => void; openMenu: 'invoice' | 'actions' | null; onMenuChange: (value: 'invoice' | 'actions' | null) => void; onInvoiceDetails: () => void; onCourierChange: () => void }) {
  const lines = item.lines ?? []
  const shipment = item.packages?.[0]
  const [copied, setCopied] = useState(false)
  const [menuPlacement, setMenuPlacement] = useState<'down' | 'up'>('down')
  const money = (value: number) => value.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })
  const delivery = deliveryText(item)
  async function copyOrderNumber() { try { await navigator.clipboard.writeText(item.orderNumber); setCopied(true); window.setTimeout(() => setCopied(false), 1400) } catch { setCopied(false) } }
  function toggleMenu(kind: 'invoice' | 'actions', event: MouseEvent<HTMLButtonElement>) {
    if (openMenu === kind) { onMenuChange(null); return }
    const trigger = event.currentTarget.getBoundingClientRect()
    const estimatedHeight = kind === 'invoice' ? 150 : 132
    const availableBelow = window.innerHeight - trigger.bottom
    setMenuPlacement(availableBelow >= estimatedHeight + 12 ? 'down' : 'up')
    onMenuChange(kind)
  }
  return <article className={`order-reference-row ${item.derivedStatus.toLowerCase()} ${item.isMicroExport ? 'micro-export' : ''} ${openMenu ? 'menu-open' : ''}`}>
    <div className="order-reference-grid">
      <label className="order-select"><input type="checkbox" checked={selected} onChange={event => onSelect(event.target.checked)} aria-label={`Sipariş ${item.orderNumber} seç`} /></label>
      <div className="order-reference-meta"><div className="order-number"><strong><i className="order-package-mark" aria-hidden="true" />#{item.orderNumber}</strong><button type="button" className="order-number-copy" onClick={copyOrderNumber} aria-label={`Sipariş numarası ${item.orderNumber} kopyala`} title={copied ? 'Kopyalandı' : 'Sipariş numarasını kopyala'}><span className="copy-icon" aria-hidden="true" /></button></div><small>Sipariş Tarihi: <DateText value={item.orderedAt} /></small><small>Paket No: {shipment?.externalPackageId ?? 'Bekleniyor'}</small><small>Teslimat No: {shipment?.cargoTrackingNumber ?? 'Bekleniyor'}</small><span className={delivery.overdue ? 'delivery-overdue' : ''}>{delivery.label && <>{delivery.label}: </>}<b>{delivery.value}</b>{delivery.note && <em>{delivery.note}</em>}</span></div>
      <div className="order-reference-buyer"><strong>{item.customerName}</strong></div>
      <div className="order-reference-products">{lines.length ? lines.map(line => { const imageUrl = line.imageUrl ?? item.primaryImageUrl; return <article key={line.id}>{imageUrl ? <img src={imageUrl} alt={`${line.title} ürün görseli`} /> : <span className="reference-product-placeholder" aria-label="Ürün görseli eşleştirmesi bekleniyor">▧</span>}<div><strong>{line.title}</strong><small>Stok Kodu: {line.sku}</small>{optionRows(line.optionSignature).map(option => <small key={`${option.label}:${option.value}`}>{option.label}: {option.value}</small>)}<small>Barkod: {line.barcode ?? '—'}</small><small>Model Kodu: {line.modelCode ?? '—'}</small></div><b className="quantity-bubble">{line.orderedQuantity}</b></article> }) : <div className="reference-no-product">Ürün bilgisi eşitleme bekliyor</div>}</div>
      <div className="order-reference-prices">{lines.length ? lines.map(line => <strong key={line.id}>{money(line.unitPrice)}</strong>) : <strong>{money(item.netAmount)}</strong>}</div>
      <div className="order-reference-cargo"><strong>{shipment?.cargoProviderName ?? item.cargoProviderName ?? 'Kargo bekleniyor'}</strong><b>{shipment?.cargoTrackingNumber ?? item.cargoTrackingNumber ?? 'Takip no bekleniyor'}</b></div>
      <div className={`order-reference-invoice ${item.invoiceStatus === 'FATURA_BEKLIYOR' ? 'invoice-pending' : 'invoice-created'}`}><small>Satış Tutarı:</small><strong>{money(item.grossAmount || item.netAmount)}</strong>{item.discountAmount > 0 && <small>Satıcı İndirim Tutarı: {money(item.discountAmount)}</small>}{item.isMicroExport && <span className="micro-invoice-chip">Mikro ihracat</span>}<span>{item.invoiceStatus === 'FATURA_BEKLIYOR' ? 'Fatura bekleniyor' : item.invoiceStatus === 'FATURA_KONTROLDE' ? 'Fatura kontrol ediliyor' : item.invoiceStatus === 'FATURA_REDDEDILDI' ? 'Fatura reddedildi' : 'Fatura kesildi'}</span>{item.invoiceStatus !== 'FATURA_BEKLIYOR' && (item.invoiceId ? <Link className="invoice-document-link" to={`/invoices/${item.invoiceId}`}>Faturayı Gör</Link> : item.invoiceDocumentUrl ? <a className="invoice-document-link" href={item.invoiceDocumentUrl} target="_blank" rel="noreferrer">Faturayı Gör</a> : null)}<div className="row-menu"><button type="button" className="row-menu-trigger" onClick={event => toggleMenu('invoice', event)} aria-expanded={openMenu === 'invoice'}>Fatura işlemleri⌄</button>{openMenu === 'invoice' && <div className={`row-popover invoice-popover opens-${menuPlacement}`} role="menu">{item.invoiceStatus === 'FATURA_BEKLIYOR' ? <><Link to={`/orders/${item.id}`} role="menuitem" className="create-invoice">Fatura Oluştur</Link><button type="button" role="menuitem" onClick={onInvoiceDetails}>Fatura &amp; Adres Bilgileri</button><Link to={`/orders/${item.id}?invoiceUpload=1`} role="menuitem">Fatura Yükle</Link></> : <><button type="button" role="menuitem" onClick={onInvoiceDetails}>Fatura &amp; Adres Bilgileri</button>{item.invoiceId && <Link to={`/invoices/${item.invoiceId}?upload=1`} role="menuitem">Fatura Yükle</Link>}<button type="button" role="menuitem" className="destructive" disabled>Faturayı Sil</button></>}</div>}</div></div>
      <div className="order-reference-actions">{shipment?.cargoTrackingNumber ? <><Link to={`/shipments/${shipment.id}`}>Kargo Etiketini A4 Yazdır</Link><Link to={`/shipments/${shipment.id}`} title="Trendyol ortak etiket çıktısı ZPL olarak desteklendiğinde açılır">Kargo Etiketini Sticker Yazdır</Link></> : <span>Etiket için takip numarası bekleniyor</span>}<div className="row-menu"><button type="button" className="order-action-menu row-menu-trigger" onClick={event => toggleMenu('actions', event)} aria-expanded={openMenu === 'actions'}>İşlemler⌄</button>{openMenu === 'actions' && <div className={`row-popover action-popover opens-${menuPlacement}`} role="menu">{shipment ? <Link to={`/shipments/${shipment.id}`} role="menuitem">İşleme Al</Link> : <button type="button" disabled>İşleme Al</button>}<button type="button" role="menuitem" onClick={onCourierChange}>Başka Kargo Firması İle Gönder</button><button type="button" role="menuitem" disabled>İptal Et</button></div>}</div></div>
    </div>
  </article>
}
function returnGroup(status: string) { const value = status.toUpperCase(); if (['APPROVED', 'COMPLETED'].includes(value)) return 'APPROVED'; if (['REJECTED', 'CANCELLED'].includes(value)) return 'REJECTED'; if (['ACTION_REQUIRED', 'WAITING_FOR_SELLER_ACTION'].includes(value)) return 'ACTION_REQUIRED'; if (['WAITING_FOR_SHIPMENT', 'IN_TRANSIT', 'RETURN_IN_TRANSIT', 'SHIPPED'].includes(value)) return 'SHIPPING'; return 'REVIEW' }
const activePlatformCodes = new Set(['TRENDYOL', 'TRENDYOL_EFATURAM'])

export function IntegrationsPage() {
  const client = useQueryClient(); const [error, setError] = useState(''); const [platform, setPlatform] = useState('TRENDYOL'); const query = useQuery({ queryKey: ['connections'], queryFn: () => hubApi<Page<Connection>>('/connections') })
  const create = useMutation({ mutationFn: (body: object) => hubApi<Connection>('/connections', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(body) }), onSuccess: () => client.invalidateQueries({ queryKey: ['connections'] }), onError: reason => setError(reason instanceof Error ? reason.message : 'Bağlantı oluşturulamadı.') })
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(''); const data = new FormData(event.currentTarget); create.mutate({ displayName: data.get('displayName'), environment: data.get('environment'), externalStoreId: data.get('externalStoreId'), apiVersion: platform === 'TRENDYOL' ? 'V2' : '1.0.0', userAgentIdentity: platform === 'TRENDYOL' ? data.get('userAgentIdentity') : null, platformCode: platform }) }
  const activeConnections = query.data?.items.filter(item => activePlatformCodes.has(item.platformCode)) ?? []
  return <section className="content f3"><div className="page-heading"><div><p className="eyebrow">Platform bağlantıları</p><h1>Trendyol ve Trendyol E-Faturam</h1><p className="lede">Aktif teslim kapsamı bu iki entegrasyonla sınırlıdır. Credential, ortam ve capability kanıtı birbirinden ayrıdır; dış yazmalar varsayılan olarak kapalıdır.</p></div><Badge value="ADR-016" /></div>
    {query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : <><div className="integration-grid">{activeConnections.map(item => <Link className="integration-card" to={`/integrations/${item.id}`} key={item.id}><div className="integration-card-top"><span className={`platform-mark ${item.platformCode.toLowerCase()}`}>{item.platformCode === 'TRENDYOL_EFATURAM' ? '▤' : '◉'}</span><span className={item.status === 'ACTIVE' || item.status === 'VERIFIED' ? 'connection-state connected' : 'connection-state'}><i />{item.status === 'ACTIVE' || item.status === 'VERIFIED' ? 'Bağlı' : 'Bağlı değil'}</span></div><h2>{item.displayName}</h2><p>{item.platformCode === 'TRENDYOL_EFATURAM' ? 'Fatura sağlayıcısı' : 'Sipariş kaynağı'}</p><div className="integration-details"><span>Ortam<strong>{item.environment}</strong></span><span>{item.platformCode === 'TRENDYOL_EFATURAM' ? 'Yerel kapsam' : 'Mağaza kimliği'}<strong>{item.externalStoreId}</strong></span><span>Credential<strong>{item.hasCredential ? 'Şifreli kayıtlı' : 'Bekleniyor'}</strong></span></div><span className="connection-button">Bağlantıyı yönet →</span></Link>)}</div>{!activeConnections.length && <Empty>İlk aktif kapsam bağlantısını aşağıdaki güvenli formdan oluşturun.</Empty>}<form className="panel form-panel integration-create" onSubmit={submit}><h2>Yeni bağlantı</h2><div className="integration-form-grid"><label>Platform<select value={platform} onChange={event => setPlatform(event.target.value)}><option value="TRENDYOL">Trendyol V2</option><option value="TRENDYOL_EFATURAM">Trendyol E-Faturam</option></select></label><label>Bağlantı adı<input name="displayName" required /></label><label>Environment<select name="environment" defaultValue="STAGE"><option>STAGE</option><option>PRODUCTION</option></select></label><label>{platform === 'TRENDYOL' ? 'Satıcı / mağaza kimliği' : 'Yerel bağlantı kapsamı'}<input name="externalStoreId" placeholder={platform === 'TRENDYOL_EFATURAM' ? 'ravencia-efaturam' : undefined} required /></label>{platform === 'TRENDYOL' && <label>User-Agent kimliği<input name="userAgentIdentity" placeholder="Firma-Adı - Entegrasyon-Adı" required /></label>}</div>{error && <div role="alert" className="error">{error}</div>}<button disabled={create.isPending}>{create.isPending ? 'Oluşturuluyor…' : 'Taslak bağlantı oluştur'}</button></form></>}
  </section>
}

export function IntegrationDetailPage() {
  const { id = '' } = useParams(); const client = useQueryClient(); const [notice, setNotice] = useState(''); const connection = useQuery({ queryKey: ['connection', id], queryFn: () => hubApi<Connection>(`/connections/${id}`) }); const capabilities = useQuery({ queryKey: ['capabilities', id], queryFn: () => hubApi<Capability[]>(`/connections/${id}/capabilities`) });
  const run = useMutation({ mutationFn: (request: { path: string; body?: object; version?: number }) => hubApi(request.path, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), ...(request.version ? { 'If-Match': `"v${request.version}"` } : {}) }, body: JSON.stringify(request.body ?? {}) }), onSuccess: () => { setNotice('İş kuyruğa alındı.'); void client.invalidateQueries({ queryKey: ['connection', id] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'İşlem tamamlanamadı.') })
  function refreshSingleOrder(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const orderNumber = String(new FormData(event.currentTarget).get('orderNumber') ?? '').trim(); if (orderNumber) run.mutate({ path: `/connections/${id}/order-sync-jobs`, body: { externalOrderId: orderNumber } }) }
  const activate = useMutation({ mutationFn: (version: number) => hubApi<Connection>(`/connections/${id}/active`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${version}"` }, body: JSON.stringify({ active: true }) }), onSuccess: () => { setNotice('Bağlantı etkinleştirildi.'); void client.invalidateQueries({ queryKey: ['connection', id] }); void client.invalidateQueries({ queryKey: ['connections'] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Bağlantı etkinleştirilemedi.') })
  async function settings(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!connection.data) return; const data = new FormData(event.currentTarget); try { const body = { displayName: data.get('displayName'), userAgentIdentity: data.get('userAgentIdentity') }; await hubApi<Connection>(`/connections/${id}`, { method: 'PATCH', headers: { 'If-Match': `"v${connection.data.version}"` }, body: JSON.stringify(body) }); setNotice('Bağlantı ayarları güncellendi.'); await client.invalidateQueries({ queryKey: ['connection', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Bağlantı ayarları güncellenemedi.') } }
  async function credential(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!connection.data) return; const data = new FormData(event.currentTarget); const body = connection.data.platformCode === 'TRENDYOL_EFATURAM' ? { email: data.get('email') || null, password: data.get('password') || null } : { apiKey: data.get('apiKey'), apiSecret: data.get('apiSecret') }; try { await hubApi(`/connections/${id}/credential`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${connection.data.version}"` }, body: JSON.stringify(body) }); setNotice('Credential şifreli olarak yenilendi; değerler tekrar gösterilmeyecek.'); await client.invalidateQueries({ queryKey: ['connection', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Credential kaydedilemedi.') } }
  async function evidence(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); const code = String(data.get('code') || ''); const capability = capabilities.data?.find(value => value.code === code); if (!capability) return; try { const constraints = String(data.get('constraintsJson') || '').trim(); await hubApi(`/connections/${id}/capabilities/${encodeURIComponent(code)}/evidence`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `\"v${capability.version}\"` }, body: JSON.stringify({ supportLevel: data.get('supportLevel'), sourceUrl: data.get('sourceUrl'), sourceVersion: data.get('sourceVersion'), environment: item.environment, storeScope: item.externalStoreId, evidenceNote: data.get('evidenceNote'), fixtureChecksum: data.get('fixtureChecksum') || null, constraintsJson: constraints || null, verifiedAt: new Date(String(data.get('verifiedAt'))).toISOString() }) }); setNotice('Capability kanıtı audit kaydıyla güncellendi.'); await client.invalidateQueries({ queryKey: ['capabilities', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Capability kanıtı kaydedilemedi.') } }
  if (connection.isLoading) return <section className="content"><Busy /></section>; if (connection.isError || !connection.data) return <section className="content"><ErrorBox error={connection.error} /></section>; const item = connection.data
  if (!activePlatformCodes.has(item.platformCode)) return <section className="content f3"><Link to="/integrations" className="back">← Platformlar</Link><div className="unknown"><strong>Bağlantı aktif kapsam dışında</strong><p>ADR-016 uyarınca panel yalnız Trendyol ve Trendyol E-Faturam ile ilerler. Kapsam dışı tarihsel bağlantılara işlem sunulmaz.</p></div></section>
  const orderReadSupported = item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE' && capabilities.data?.some(cap => cap.code === 'ORDER_READ' && cap.supportLevel === 'SUPPORTED') === true; const referenceReadSupported = item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE' && capabilities.data?.some(cap => cap.code === 'REFERENCE_READ' && cap.supportLevel === 'SUPPORTED') === true
  return <section className="content f3"><div className="page-heading"><div><Link to="/integrations" className="back">← Platformlar</Link><h1>{item.displayName}</h1><p className="lede">{item.environment} · {item.platformCode === 'TRENDYOL_EFATURAM' ? 'yerel kapsam' : 'mağaza'} {item.externalStoreId} · API {item.apiVersion}</p></div><Badge value={item.status} /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="grid"><article><small>Credential</small><strong>{item.hasCredential ? 'Şifreli kayıtlı' : 'Bekleniyor'}</strong><p>API key/secret hiçbir yanıtta gösterilmez.</p></article><article><small>Son test</small><strong><DateText value={item.lastTestedAt} /></strong><p>{item.lastErrorCode ?? 'Hata kaydı yok'}</p></article><article><small>Dış yazma</small><strong>Kapalı</strong><p>Stage safe-write kanıtı ve ayrı anahtar gerekir.</p></article></div>
    {item.platformCode === 'TRENDYOL' && item.status === 'VERIFIED' && <div className="panel"><h2>Bağlantıyı etkinleştir</h2><p>Başarılı bağlantı testi kanıtı korunarak yalnız bu Trendyol bağlantısı etkinleştirilir. Dış yazmalar kapalı kalır.</p><button disabled={activate.isPending} onClick={() => activate.mutate(item.version)}>{activate.isPending ? 'Etkinleştiriliyor…' : 'Bağlantıyı ACTIVE yap'}</button></div>}
    {orderReadSupported && <div className="panel"><h2>Salt-okunur sipariş eşitleme</h2><p>Yalnız ORDER_READ=SUPPORTED kanıtı ile platform siparişleri okunur. Bu işlem dış platforma yazmaz.</p><div className="button-row"><button disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/order-sync-jobs`, body: { externalOrderId: null } })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Siparişleri eşitle'}</button></div><form className="inline-form" onSubmit={refreshSingleOrder}><label>Sipariş numarasıyla yenile<input name="orderNumber" inputMode="numeric" pattern="[0-9]+" placeholder="Örn. 1238693012" required /></label><button className="secondary" disabled={run.isPending}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Yalnız bu siparişi yenile'}</button></form></div>}
    {referenceReadSupported && <div className="panel"><h2>Salt-okunur katalog referansları</h2><p>Yalnız REFERENCE_READ=SUPPORTED kanıtıyla kategori ve marka listeleri yerel snapshot olarak saklanır. Trendyol’a yazılmaz.</p><div className="button-row"><button disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/reference-sync-jobs?resourceType=CATEGORIES` })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Kategorileri eşitle'}</button><button className="secondary" disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/reference-sync-jobs?resourceType=BRANDS` })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Markaları eşitle'}</button><Link className="button-link secondary" to="/mappings/categories?view=brands">Marka eşlemelerine git</Link></div></div>}
    {item.platformCode === 'TRENDYOL' && <form className="panel form-panel" onSubmit={settings}><h2>Bağlantı ayarları</h2><label>Bağlantı adı<input name="displayName" defaultValue={item.displayName} required /></label><label>User-Agent kimliği<input name="userAgentIdentity" placeholder="Firma-Adı - Entegrasyon-Adı" autoComplete="off" required /></label><button>Bağlantı ayarlarını kaydet</button></form>}
    {item.platformCode === 'TRENDYOL_EFATURAM' && <article className="panel"><h2>E-Faturam hesabı otomatik yönetilir</h2><p>Firma kimliği, kullanıcı kimliği ve varsayılan fatura serisi panelden girilmez. E-posta/parola ile açılan E-Faturam oturumundaki firma kapsamı ve varsayılan seri kullanılır.</p><div className="card-list"><div className="record-card"><span><strong>Belge türü</strong><small>Kurumsal ve E-Fatura mükellefi: TEMELFATURA; diğer siparişler: EARSIVFATURA</small></span><Badge value="AUTO" /></div><div className="record-card"><span><strong>İnternet satışı ek alanları</strong><small>Kullanıcı ayarı değildir; gerekli olduğunda Trendyol siparişi ve resmî kargo kataloğundan otomatik hazırlanır.</small></span><Badge value="AUTO" /></div></div></article>}
    <div className="split"><form className="panel form-panel" onSubmit={credential}><h2>Credential döndür</h2>{item.platformCode === 'TRENDYOL_EFATURAM' ? <><label>E-Faturam e-postası<input name="email" type="email" autoComplete="username" required /></label><label>E-Faturam parolası<input name="password" type="password" autoComplete="new-password" required /></label><p>Firma ve kullanıcı kimlikleri giriş tokenından alınır; mali hesap bilgisi panelde saklanmaz veya tekrar gösterilmez.</p></> : <><label>API key<input name="apiKey" type="password" autoComplete="off" required /></label><label>API secret<input name="apiSecret" type="password" autoComplete="new-password" required /></label></>}<button disabled={run.isPending}>Şifreli kaydet</button><button type="button" className="secondary" disabled={!item.hasCredential || run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/test-jobs` })}>Bağlantıyı test et</button></form>
      <div className="panel"><h2>Capability kanıtları</h2>{capabilities.isLoading ? <Busy /> : capabilities.isError ? <ErrorBox error={capabilities.error} /> : <div className="capability-list">{capabilities.data?.map(cap => <div key={cap.code}><span><strong>{cap.code}</strong><small><DateText value={cap.verifiedAt} /></small></span><Badge value={cap.supportLevel} /></div>)}</div>}</div></div>
    {capabilities.data?.length ? <form className="panel form-panel" onSubmit={evidence}><h2>Stage/SIT capability kanıtı kaydet</h2><p>Yalnız Owner/Administrator kullanabilir. Write capability SUPPORTED için Stage/SIT fixture SHA-256 zorunludur.</p><label>Capability<select name="code">{capabilities.data.map(cap => <option key={cap.code}>{cap.code}</option>)}</select></label><label>Destek seviyesi<select name="supportLevel" defaultValue="UNKNOWN"><option>UNKNOWN</option><option>SUPPORTED</option><option>NOT_SUPPORTED</option></select></label><label>Resmî kaynak URL<input name="sourceUrl" type="url" placeholder="https://developers.trendyol.com veya developers.trendyolefaturam.com/..." required /></label><label>Kaynak sürümü<input name="sourceVersion" defaultValue="V2" required /></label><label>Doğrulama zamanı<input name="verifiedAt" type="datetime-local" required /></label><label>Kanıt notu<textarea name="evidenceNote" maxLength={1000} required /></label><label>Stage/SIT fixture SHA-256<input name="fixtureChecksum" minLength={64} maxLength={64} /></label><label>Kısıtlar JSON<textarea name="constraintsJson" placeholder='{"allowedActions":["PICKING","TRACKING_NUMBER"]}' /></label><button>Kanıtı kaydet</button></form> : null}
  </section>
}

export function OrdersPage() {
  const [filterForm, setFilterForm] = useState<OrderFilters>(initialOrderFilters); const [filters, setFilters] = useState<OrderFilters>(initialOrderFilters); const [advancedFilters, setAdvancedFilters] = useState(false); const [pageSize, setPageSize] = useState(20); const [page, setPage] = useState(1); const [selectedIds, setSelectedIds] = useState<string[]>([]); const [menu, setMenu] = useState<{ orderId: string; kind: 'invoice' | 'actions' } | null>(null); const [invoiceInfoOrder, setInvoiceInfoOrder] = useState<Order | null>(null); const [courierOrder, setCourierOrder] = useState<Order | null>(null)
  const query = useQuery({ queryKey: ['orders'], queryFn: () => hubApi<Page<Order>>('/orders?limit=200') })
  const statuses = [['ALL', 'Tümü'], ['NEW', 'Yeni'], ['PROCESSING', 'Hazırlanıyor'], ['SHIPPED', 'Kargoda'], ['DELIVERED', 'Teslim Edildi'], ['CANCELLED', 'İptal/İade']] as const
  const all = query.data?.items ?? []; const normalized = filters.search.trim().toLocaleLowerCase('tr-TR')
  const cargos = Array.from(new Set(all.map(item => item.packages?.[0]?.cargoProviderName ?? item.cargoProviderName).filter((value): value is string => !!value)))
  const platforms = Array.from(new Set(all.map(item => item.platformCode).filter(Boolean)))
  const updateFilter = <K extends keyof OrderFilters>(key: K, value: OrderFilters[K]) => setFilterForm(current => ({ ...current, [key]: value }))
  const applyFilters = () => { setFilters(filterForm); setPage(1) }
  const clearFilters = () => { setFilterForm(initialOrderFilters); setFilters(initialOrderFilters); setPage(1) }
  const selectStatus = (status: string) => { const next = { ...filterForm, status }; setFilterForm(next); setFilters(current => ({ ...current, status })); setPage(1) }
  const items = all.filter(item => {
    const searchValues = [item.orderNumber, item.customerName, item.customerEmail ?? '', item.customerTaxOrIdentityNumber ?? '', item.cargoTrackingNumber ?? '', ...(item.packages ?? []).flatMap(pack => [pack.externalPackageId, pack.cargoTrackingNumber ?? '', pack.cargoProviderName ?? '']), ...(item.lines ?? []).flatMap(line => [line.title, line.sku, line.barcode ?? '', line.modelCode ?? '', line.optionSignature ?? ''])]
    const ordered = new Date(item.orderedAt); const from = filters.dateFrom ? new Date(`${filters.dateFrom}T00:00:00`) : null; const to = filters.dateTo ? new Date(`${filters.dateTo}T23:59:59.999`) : null; const isClosed = ['DELIVERED', 'CANCELLED'].includes(item.derivedStatus.toUpperCase())
    return (filters.status === 'ALL' || item.derivedStatus.toUpperCase() === filters.status) && (filters.platform === 'ALL' || item.platformCode === filters.platform) && (filters.listing === 'ALL' || (filters.listing === 'OPEN' ? !isClosed : isClosed)) && (filters.cargo === 'ALL' || (item.packages?.[0]?.cargoProviderName ?? item.cargoProviderName) === filters.cargo) && (filters.invoice === 'ALL' || item.invoiceStatus === filters.invoice) && (!from || ordered >= from) && (!to || ordered <= to) && (!normalized || searchValues.some(value => value.toLocaleLowerCase('tr-TR').includes(normalized)))
  })
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize)); const safePage = Math.min(page, totalPages); const pageItems = items.slice((safePage - 1) * pageSize, safePage * pageSize); const allPageSelected = pageItems.length > 0 && pageItems.every(item => selectedIds.includes(item.id))
  function updateSelection(id: string, checked: boolean) { setSelectedIds(current => checked ? Array.from(new Set([...current, id])) : current.filter(value => value !== id)) }
  function togglePageSelection(checked: boolean) { setSelectedIds(current => checked ? Array.from(new Set([...current, ...pageItems.map(item => item.id)])) : current.filter(id => !pageItems.some(item => item.id === id))) }
  return <section className="content f3 orders-page"><div className="page-heading"><div><p className="eyebrow">Sipariş yönetimi</p><h1>Siparişler</h1><p className="lede">Sipariş, müşteri, ürün, termin, fatura ve kargo bilgilerini tek ekrandan yönetin.</p></div></div>
    <div className="order-tabs" role="tablist" aria-label="Sipariş durumları">{statuses.map(([value,label]) => <button type="button" role="tab" aria-selected={filters.status === value} className={filters.status === value ? 'active' : ''} key={value} onClick={() => selectStatus(value)}><span>{label}</span><b>{value === 'ALL' ? all.length : all.filter(x => x.derivedStatus.toUpperCase() === value).length}</b></button>)}</div>
    <section className="order-filter-panel" aria-label="Sipariş filtreleri"><div className="order-filter-primary"><button type="button" className="bulk-action" disabled={!selectedIds.length}>Toplu işlemler⌄</button><label className="order-search"><span aria-hidden="true">⌕</span><input aria-label="Sipariş ara" value={filterForm.search} onChange={event => updateFilter('search', event.target.value)} placeholder="Sipariş no, paket no, takip no, alıcı, stok/model kodu veya barkod ara…" onKeyDown={event => { if (event.key === 'Enter') applyFilters() }} /></label><label>Platform<select value={filterForm.platform} onChange={event => updateFilter('platform', event.target.value)}><option value="ALL">Tüm platformlar</option>{platforms.map(value => <option key={value} value={value}>{value === 'TRENDYOL' ? 'Trendyol' : value}</option>)}</select></label><label>Sipariş durumu<select value={filterForm.status} onChange={event => updateFilter('status', event.target.value)}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><button type="button" className="filter-toggle" onClick={() => setAdvancedFilters(value => !value)} aria-expanded={advancedFilters}>Gelişmiş Filtreler {advancedFilters ? '⌃' : '⌄'}</button><button type="button" className="secondary filter-clear" onClick={clearFilters}>Temizle</button><button type="button" className="filter-apply" onClick={applyFilters}>Uygula</button></div>{advancedFilters && <div className="order-filter-advanced"><label>Listeleme durumu<select value={filterForm.listing} onChange={event => updateFilter('listing', event.target.value)}><option value="ALL">Tüm kayıtlar</option><option value="OPEN">Açık siparişler</option><option value="CLOSED">Kapanan siparişler</option></select></label><label>Sipariş tarihi başlangıç<input type="date" value={filterForm.dateFrom} onChange={event => updateFilter('dateFrom', event.target.value)} /></label><label>Sipariş tarihi bitiş<input type="date" value={filterForm.dateTo} onChange={event => updateFilter('dateTo', event.target.value)} /></label><label>Kargo<select value={filterForm.cargo} onChange={event => updateFilter('cargo', event.target.value)}><option value="ALL">Tüm kargolar</option>{cargos.map(value => <option key={value}>{value}</option>)}</select></label><label>Fatura<select value={filterForm.invoice} onChange={event => updateFilter('invoice', event.target.value)}><option value="ALL">Tüm durumlar</option><option value="FATURA_BEKLIYOR">Fatura bekliyor</option><option value="FATURA_KESILDI">Fatura kesildi</option><option value="FATURA_REDDEDILDI">Fatura reddedildi</option></select></label><label>Sayfada<select value={pageSize} onChange={event => { setPageSize(Number(event.target.value)); setPage(1) }}>{[10, 20, 50, 100, 150].map(value => <option key={value} value={value}>{value} sipariş</option>)}</select></label></div>}</section>
    {query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : !all.length ? <Empty>Aktif ve kanıtlanmış bağlantıdan sipariş eşitlemesi çalıştırıldığında kayıtlar burada görünür.</Empty> : !items.length ? <Empty>Seçili durum ve filtrelerle eşleşen sipariş yok.</Empty> : <><div className="order-reference-table"><div className="order-reference-head"><label className="order-select"><input type="checkbox" checked={allPageSelected} onChange={event => togglePageSelection(event.target.checked)} aria-label="Sayfadaki siparişleri seç" /></label><strong>Sipariş Bilgileri</strong><strong>Alıcı</strong><strong>Bilgiler</strong><strong>Birim Fiyat</strong><strong>Kargo</strong><strong>Fatura</strong><strong>Durum</strong></div>{pageItems.map(item => <OrderReferenceRow item={item} key={item.id} selected={selectedIds.includes(item.id)} onSelect={checked => updateSelection(item.id, checked)} openMenu={menu?.orderId === item.id ? menu.kind : null} onMenuChange={kind => setMenu(kind ? { orderId: item.id, kind } : null)} onInvoiceDetails={() => { setMenu(null); setInvoiceInfoOrder(item) }} onCourierChange={() => { setMenu(null); setCourierOrder(item) }} />)}</div><div className="order-pagination"><span>{items.length} siparişten {(safePage - 1) * pageSize + 1}–{Math.min(safePage * pageSize, items.length)} arası gösteriliyor</span><div><button type="button" disabled={safePage <= 1} onClick={() => setPage(safePage - 1)}>‹ Önceki</button><b>{safePage} / {totalPages}</b><button type="button" disabled={safePage >= totalPages} onClick={() => setPage(safePage + 1)}>Sonraki ›</button></div></div></>}
    {invoiceInfoOrder && <InvoiceInfoModal item={invoiceInfoOrder} onClose={() => setInvoiceInfoOrder(null)} />}{courierOrder && <CourierChangeModal item={courierOrder} onClose={() => setCourierOrder(null)} />}
  </section>
}

export function OrderDetailPage() {
  const { id = '' } = useParams(); const location = useLocation(); const navigate = useNavigate(); const [invoiceMessage, setInvoiceMessage] = useState('')
  const query = useQuery({ queryKey: ['order', id], queryFn: () => hubApi<OrderDetail>(`/orders/${id}`) })
  const connections = useQuery({ queryKey: ['connections'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const provider = connections.data?.items.find(x => x.platformCode === 'TRENDYOL_EFATURAM' && (x.status === 'ACTIVE' || x.status === 'VERIFIED'))
  const createInvoice = useMutation({ mutationFn: (packageId: string) => { if (!query.data || !provider) throw new Error('Aktif E-Faturam bağlantısı zorunludur.'); return hubApi<CreatedInvoice>('/invoices', { method: 'POST', headers: { 'Idempotency-Key': `invoice:${query.data.id}:${packageId}` }, body: JSON.stringify({ orderId: query.data.id, packageId, providerConnectionId: provider.id, originalInvoiceId: null }) }) }, onSuccess: invoice => navigate(`/invoices/${invoice.id}${new URLSearchParams(location.search).get('invoiceUpload') === '1' ? '?upload=1' : ''}`), onError: error => setInvoiceMessage(error instanceof Error ? error.message : 'Fatura taslağı oluşturulamadı.') })
  if (query.isLoading) return <section className="content"><Busy /></section>; if (query.isError || !query.data) return <section className="content"><ErrorBox error={query.error} /></section>; const item = query.data
  const billingReady = !!provider?.hasCredential && item.invoiceStatus === 'FATURA_BEKLIYOR'
  return <section className="content f3 order-detail-page"><Link to="/orders" className="back">← Siparişler</Link>{invoiceMessage && <div role="alert" className="error">{invoiceMessage}</div>}
    <div className="detail-grid"><article className="panel"><h2>Müşteri ve fatura bilgileri</h2><dl className="details"><dt>Ad soyad / unvan</dt><dd>{item.customerName}</dd><dt>E-posta</dt><dd>{item.customerEmail ?? '—'}</dd><dt>TC / vergi no</dt><dd>{item.customerTaxOrIdentityNumber ?? '—'}</dd><dt>Sipariş türü</dt><dd>{orderTypeLabel(item.orderType)}</dd><dt>Termin</dt><dd className={item.shipmentDueAt && new Date(item.shipmentDueAt).getTime() - Date.now() < 86_400_000 ? 'deadline critical' : ''}>{remainingText(item.shipmentDueAt)}</dd></dl></article><article className="panel"><h2>Adresler</h2><p><strong>Teslimat:</strong> {addressText(item.shipmentAddressJson)}</p><p><strong>Fatura:</strong> {addressText(item.invoiceAddressJson)}</p></article></div>
    <div className="panel order-lines-panel"><h2>Ürünler ve varyantlar</h2><div className="data-table compact" role="table">{item.lines.map(line => <div role="row" key={line.id}><span className="order-line">{line.imageUrl ? <img className="operation-image" src={line.imageUrl} alt="" /> : <span className="order-thumb" aria-hidden="true">▧</span>}<span><strong>{line.title}</strong><small>{line.optionSignature && line.optionSignature !== '-' ? `${line.optionSignature} · ` : ''}{line.modelCode ? `Model ${line.modelCode} · ` : ''}{line.sku}{line.barcode ? ` · ${line.barcode}` : ''}</small></span></span><span>{line.orderedQuantity} adet</span><span>{line.unitPrice.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</span><span>KDV %{line.vatRate}</span></div>)}</div><div className="totals"><span>Ara toplam <strong>{item.grossAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</strong></span><span>İndirim <strong>{item.discountAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</strong></span><span>Genel toplam <strong>{item.netAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</strong></span></div></div>
    <div className="panel order-package-panel"><h2>Paket, kargo ve fatura</h2>{new URLSearchParams(location.search).get('invoiceUpload') === '1' && <div className="notice"><strong>Fatura belgesi yükleme</strong><p>Belgeyi güvenli biçimde eklemek için önce yerel fatura taslağını oluşturun. Bu işlem belgenizi Trendyol’a veya E‑Faturam’a göndermez.</p></div>}{!item.packages.length ? <Empty>Paket verisi henüz gelmedi.</Empty> : <div className="card-list">{item.packages.map(pack => <div className="record-card" key={pack.id}><span><strong>{pack.externalPackageId}</strong><small>{pack.cargoProviderName ?? 'Kargo firması yok'} · {pack.cargoTrackingNumber ?? 'Takip numarası yok'}</small></span><span><Badge value={pack.status} />{pack.cargoTrackingNumber && <Link className="button-link secondary compact-button" to={`/shipments/${pack.id}`}>Kargo barkod etiketi</Link>}<Link className="button-link secondary compact-button" to={`/shipments/${pack.id}`}>Kargo işlemleri</Link><button disabled={!billingReady || createInvoice.isPending} onClick={() => createInvoice.mutate(pack.id)}>{item.invoiceStatus === 'FATURA_BEKLIYOR' ? (createInvoice.isPending ? 'Hazırlanıyor…' : new URLSearchParams(location.search).get('invoiceUpload') === '1' ? 'Taslak oluştur ve yükle' : 'Fatura kes') : 'Fatura mevcut'}</button></span></div>)}</div>}{!billingReady && item.invoiceStatus === 'FATURA_BEKLIYOR' && <div className="unknown"><strong>E-Faturam bağlantısı hazır değil</strong><p>Şifreli ve aktif provider bağlantısı olmadan mali belge taslağı oluşturulmaz.</p><Link className="button-link" to="/integrations">Bağlantıyı yönet</Link></div>}</div>
  </section>
}

export function ShipmentsPage() { const query = useQuery({ queryKey: ['shipments'], queryFn: () => hubApi<Page<Shipment>>('/shipments') }); return <ListPage eyebrow="Operasyon" title="Gönderiler" description="Paket durumu geriye alınmaz; desteklenmeyen aksiyon ve etiket biçimleri gösterilmez.">{query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : !query.data?.items.length ? <Empty>Order ingestion sonrasında shipment package kayıtları burada görünür.</Empty> : <div className="data-table" role="table">{query.data.items.map(item => <Link role="row" to={`/shipments/${item.id}`} key={item.id}><span><strong>{item.orderNumber}</strong><small>Paket {item.externalPackageId}</small></span><Badge value={item.status} /><span>{item.cargoTrackingNumber ?? '—'}</span><span><DateText value={item.statusOccurredAt} /></span></Link>)}</div>}</ListPage> }

export function ShipmentDetailPage() {
  const { id = '' } = useParams(); const client = useQueryClient(); const [notice, setNotice] = useState(''); const query = useQuery({ queryKey: ['shipment', id], queryFn: () => hubApi<ShipmentDetail>(`/shipments/${id}`) })
  async function action(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { JSON.parse(String(data.get('payloadJson') || '{}')); await hubApi(`/shipments/${id}/actions`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.package.version}"` }, body: JSON.stringify({ action: data.get('action'), payloadJson: data.get('payloadJson') }) }); setNotice('Paket aksiyonu kuyruğa alındı; sonuç read-back ile doğrulanacak.'); await client.invalidateQueries({ queryKey: ['shipment', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Aksiyon başlatılamadı.') } }
  async function label(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { await hubApi(`/shipments/${id}/common-label-jobs`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.package.version}"` }, body: JSON.stringify({ boxQuantity: Number(data.get('boxQuantity')), volumetricHeight: Number(data.get('volumetricHeight')) }) }); setNotice('Ortak etiket işi kuyruğa alındı.'); await client.invalidateQueries({ queryKey: ['shipment', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Etiket işi başlatılamadı.') } }
  if (query.isLoading) return <section className="content"><Busy /></section>; if (query.isError || !query.data) return <section className="content"><ErrorBox error={query.error} /></section>; const item = query.data
  return <section className="content f3"><Link to="/shipments" className="back">← Gönderiler</Link><div className="page-heading"><div><p className="eyebrow">Gönderi detayı</p><h1>{item.package.orderNumber}</h1><p className="lede">Paket {item.package.externalPackageId}</p></div><Badge value={item.package.status} /></div>{notice && <div role="status" className="notice">{notice}</div>}<div className="split"><article className="panel"><h2>Paket</h2><dl className="details"><dt>Platform durumu</dt><dd>{item.package.rawStatus}</dd><dt>Takip numarası</dt><dd>{item.package.cargoTrackingNumber ?? '—'}</dd><dt>Güncelleme</dt><dd><DateText value={item.package.statusOccurredAt} /></dd></dl><h3>Belgeler</h3>{item.documents.length ? <ul className="plain-list">{item.documents.map(document => <li key={document.id}><strong>{document.documentKind} · {document.format}</strong><span>v{document.documentVersion} · {document.source}</span></li>)}</ul> : <p>Henüz belge yok.</p>}</article><article className="panel"><h2>Trendyol paket aksiyonu</h2>{item.allowedActions.length ? <form className="form-grid" onSubmit={action}><label>Aksiyon<select name="action">{item.allowedActions.map(value => <option key={value}>{value}</option>)}</select></label><label>Resmî aksiyon payload JSON<textarea name="payloadJson" defaultValue="{}" required /></label><button>Aksiyonu kuyruğa al</button></form> : <div className="unknown"><strong>Shipment write kapalı</strong><p>Stage/SIT capability kanıtı olmadan dış aksiyon gösterilmez.</p></div>}<h2>Ortak kargo etiketi</h2>{item.supportedLabelFormats.length && item.package.cargoTrackingNumber ? <form className="inline-form" onSubmit={label}><label>Koli adedi<input name="boxQuantity" type="number" min="1" max="50" defaultValue="1" required /></label><label>Desi / hacim<input name="volumetricHeight" type="number" min="0" max="10000" step="0.01" defaultValue="1" required /></label><button>Etiket oluştur</button></form> : <p className="notice">Etiket capability'si veya takip numarası yok.</p>}</article></div></section>
}

export function ReturnsPage() {
  const [status, setStatus] = useState('ACTION_REQUIRED'); const [search, setSearch] = useState(''); const [cargo, setCargo] = useState('ALL')
  const query = useQuery({ queryKey: ['returns'], queryFn: () => hubApi<Page<ReturnClaim>>('/returns?limit=200') })
  const items = query.data?.items ?? []; const normalized = search.trim().toLocaleLowerCase('tr-TR')
  const visible = items.filter(item => (status === 'ALL' || returnGroup(item.status) === status) && (cargo === 'ALL' || item.cargoProviderName === cargo) && (!normalized || [item.externalClaimId, item.orderNumber, item.customerName, item.reasonText ?? ''].some(value => value.toLocaleLowerCase('tr-TR').includes(normalized))))
  const tabs = [['ALL', 'İade Talepleri'], ['SHIPPING', 'Kargo Aşamasında'], ['ACTION_REQUIRED', 'Aksiyon Bekleyen'], ['APPROVED', 'Onaylanmış'], ['REJECTED', 'Reddedilmiş'], ['REVIEW', 'İnceleniyor']] as const
  const cargoOptions = Array.from(new Set(items.map(x => x.cargoProviderName).filter(Boolean))) as string[]
  return <section className="content f3 returns-page"><div className="page-heading"><div><p className="eyebrow">Satış sonrası</p><h1>İadeler</h1><p className="lede">Talep, kargo, karar ve stok kabul süreçleri tek çalışma alanında.</p></div><Badge value="LIVE READ" /></div><div className="return-tabs" role="tablist">{tabs.map(([value, label]) => <button key={value} type="button" role="tab" aria-selected={status === value} className={status === value ? 'active' : ''} onClick={() => setStatus(value)}>{label}<b>{value === 'ALL' ? items.length : items.filter(x => returnGroup(x.status) === value).length}</b></button>)}</div><div className="return-toolbar"><label className="order-search"><span aria-hidden="true">⌕</span><input aria-label="İade ara" placeholder="İade, sipariş veya müşteri ara…" value={search} onChange={event => setSearch(event.target.value)} /></label><label>Kargo<select value={cargo} onChange={event => setCargo(event.target.value)}><option value="ALL">Tüm kargolar</option>{cargoOptions.map(value => <option key={value}>{value}</option>)}</select></label></div><div className="panel return-workspace">{query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : !visible.length ? <Empty>{items.length ? 'Seçili filtreyle eşleşen iade yok.' : 'Kanıtlanmış iade eşitlemesi sonrasında talepler burada görünür.'}</Empty> : <div className="return-card-list">{visible.map(item => <Link className="return-card" to={`/returns/${item.id}`} key={item.id}>{item.primaryImageUrl ? <img className="operation-image" src={item.primaryImageUrl} alt="" /> : <span className="return-thumb" aria-hidden="true">↩</span>}<span><strong>{item.externalClaimId}</strong><small>Sipariş #{item.orderNumber} · {item.customerName}</small><small>{item.reasonText ?? 'Neden belirtilmedi'}</small></span><span><small>Sipariş tarihi</small><strong><DateText value={item.orderedAt} /></strong><small>{item.productCount} ürün</small></span><span><small>Otomatik işlem süresi</small><strong className={item.actionDueAt && new Date(item.actionDueAt).getTime() - Date.now() < 86_400_000 ? 'deadline critical' : ''}>{remainingText(item.actionDueAt)}</strong><small>{item.cargoProviderName ?? 'Kargo bilgisi yok'} · {item.cargoTrackingNumber ?? '—'}</small></span><span><strong>{item.orderAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</strong><Badge value={item.status} /></span></Link>)}</div>}</div></section>
}

export function ReturnDetailPage() {
  const { id = '' } = useParams(); const client = useQueryClient(); const [notice, setNotice] = useState(''); const [evidenceAssetIds, setEvidenceAssetIds] = useState<string[]>([]); const [action, setAction] = useState('APPROVE'); const [reasonId, setReasonId] = useState('')
  const query = useQuery({ queryKey: ['return', id], queryFn: () => hubApi<ReturnDetail>(`/returns/${id}`) })
  const reasons = useQuery({ queryKey: ['return-reasons', id], queryFn: () => hubApi<ReturnIssueReason[]>(`/returns/${id}/rejection-reasons`), enabled: query.data?.allowedActions.includes('REJECT') === true, retry: false })
  const selectedReason = reasons.data?.find(x => x.id === reasonId)
  async function uploadFile(file: File) { if (!file.size) return; const body = new FormData(); body.set('file', file); try { const asset = await hubApi<{ id: string }>('/files/return-evidence', { method: 'POST', body }); setEvidenceAssetIds(ids => ids.includes(asset.id) ? ids : [...ids, asset.id]); setNotice('Kanıt güvenli özel depoya yüklendi.') } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Kanıt yüklenemedi.') } }
  async function decide(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { await hubApi(`/returns/${id}/actions`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.version}"` }, body: JSON.stringify({ action, reasonCode: action === 'REJECT' ? reasonId : null, explanation: action === 'REJECT' ? data.get('explanation') : null, evidenceAssetIds }) }); setNotice('İade kararı kuyruğa alındı; uzak sonuç eşitlemeyle doğrulanacak.'); await client.invalidateQueries({ queryKey: ['return', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'İade kararı başlatılamadı.') } }
  async function disposition(event: FormEvent<HTMLFormElement>, line: ReturnLine) { event.preventDefault(); const data = new FormData(event.currentTarget); try { await hubApi(`/returns/${id}/stock-dispositions`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify({ returnLineId: line.id, disposition: data.get('disposition'), quantity: Number(data.get('quantity')), reason: data.get('reason') }) }); setNotice('İade stok kararı kaydedildi. Yalnız Satılabilir seçimi eldeki stoğu artırır.'); await client.invalidateQueries({ queryKey: ['return', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Stok kararı kaydedilemedi.') } }
  if (query.isLoading) return <section className="content"><Busy /></section>; if (query.isError || !query.data) return <section className="content"><ErrorBox error={query.error} /></section>; const item = query.data; const lines = item.lines ?? []
  return <section className="content f3 return-detail-page"><Link to="/returns" className="back">← İadeler</Link><div className="page-heading"><div><p className="eyebrow">İade detayı · Claim {item.externalClaimId}</p><h1>{item.orderNumber}</h1><p className="lede">{item.customerName} · {item.orderAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</p></div><Badge value={item.status} /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="detail-grid"><article className="panel"><h2>Talep ve süre</h2><dl className="details"><dt>Platform durumu</dt><dd>{item.rawStatus}</dd><dt>Neden</dt><dd>{item.reasonText ?? 'Belirtilmedi'}</dd><dt>Sipariş tarihi</dt><dd><DateText value={item.orderedAt} /></dd><dt>Otomatik işlem</dt><dd className={item.actionDueAt && new Date(item.actionDueAt).getTime() - Date.now() < 86_400_000 ? 'deadline critical' : ''}>{remainingText(item.actionDueAt)}</dd><dt>Kargo</dt><dd>{item.cargoProviderName ?? '—'} · {item.cargoTrackingNumber ?? '—'}</dd></dl></article><article className="panel"><h2>Onay / ret</h2>{item.allowedActions.length ? <form className="form-grid" onSubmit={decide}><label>Karar<select name="action" value={action} onChange={event => setAction(event.target.value)}>{item.allowedActions.filter(value => value === 'APPROVE' || value === 'REJECT').map(value => <option key={value}>{value}</option>)}</select></label>{action === 'REJECT' && <><label>Trendyol ret nedeni<select value={reasonId} onChange={event => setReasonId(event.target.value)} required><option value="">Seçin</option>{reasons.data?.map(reason => <option key={reason.id} value={reason.id}>{reason.name}</option>)}</select></label><label>Açıklama<textarea name="explanation" maxLength={500} required /></label><label>Kanıt (PDF/JPEG/PNG, en fazla 10 MiB)<input name="file" type="file" accept="application/pdf,image/jpeg,image/png" onChange={event => { const file = event.currentTarget.files?.[0]; if (file) void uploadFile(file) }} /></label><small>{evidenceAssetIds.length} kanıt hazır{selectedReason?.evidenceRequired ? ' · bu neden için zorunlu' : ''}</small></>}<button disabled={action === 'REJECT' && (!reasonId || (selectedReason?.evidenceRequired && !evidenceAssetIds.length))}>Kararı kuyruğa al</button></form> : <div className="unknown"><strong>Dış iade aksiyonu kapalı</strong><p>Stage/SIT capability kanıtı ve dış yazma onayı olmadan onay veya ret sunulmaz.</p></div>}</article></div>
    <div className="panel"><h2>İade paketi ürünleri ve stok kabulü</h2><p className="notice"><strong>Stok otomatik artmaz.</strong> Ürün fiziksel olarak kontrol edildikten sonra “Satılabilir” seçilirse stok artar; Karantina, Hasarlı ve Teslim Alınmadı seçimleri stoğu artırmaz.</p>{!lines.length ? <Empty>İade satırı bulunamadı.</Empty> : <div className="return-line-list">{lines.map(line => <article className="return-line" key={line.id}>{line.imageUrl ? <img className="operation-image" src={line.imageUrl} alt="" /> : <span className="operation-image placeholder">▧</span>}<span><strong>{line.title}</strong><small>{line.sku}{line.barcode ? ` · ${line.barcode}` : ''}</small><small>{line.quantity} adet · kalan karar {line.remainingQuantity}</small></span>{item.stockDispositionAvailable && line.remainingQuantity > 0 ? <form className="stock-disposition" onSubmit={event => disposition(event, line)}><select name="disposition" aria-label="Stok kabul kararı"><option value="PASS">Satılabilir — stoğa ekle</option><option value="QUARANTINE">Karantina — stoğa ekleme</option><option value="DAMAGED">Hasarlı — stoğa ekleme</option><option value="NOT_RECEIVED">Teslim alınmadı</option></select><input name="quantity" type="number" min="0.01" max={line.remainingQuantity} step="0.01" defaultValue={line.remainingQuantity} required /><input name="reason" placeholder="Kontrol notu" required /><button>Kararı kaydet</button></form> : <Badge value={line.remainingQuantity === 0 ? 'TAMAMLANDI' : line.hasInventoryMapping ? 'ONAY_BEKLIYOR' : 'STOK_ESLEME_GEREKLI'} />}</article>)}</div>}</div>
  </section>
}

export function MappingPage({ kind }: { kind: 'categories' | 'attributes' }) {
  const client = useQueryClient(); const [platform, setPlatform] = useState('TRENDYOL'); const [connectionId, setConnectionId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState(''); const [localSearch, setLocalSearch] = useState(''); const [externalSearch, setExternalSearch] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const localCategories = useQuery({ queryKey: ['categories', 'mapping'], queryFn: () => hubApi<Page<LocalCategory>>('/catalog/categories?limit=200'), enabled: kind === 'categories' })
  const currentCategory = useQuery({ queryKey: ['category', localId, 'mapping'], queryFn: () => hubApi<LocalCategory>(`/catalog/categories/${localId}`), enabled: !!localId })
  const localAttributes = useQuery({ queryKey: ['attributes', 'mapping-builder'], queryFn: () => hubApi<Page<LocalAttribute>>('/catalog/attributes?limit=200') })
  const requirements = useQuery({ queryKey: ['category-requirements', localId, 'mapping'], queryFn: () => hubApi<CategoryRequirementView[]>(`/catalog/categories/${localId}/attribute-requirements`), enabled: !!localId, retry: false })
  const references = useQuery({ queryKey: ['reference-categories', connectionId], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories?connectionId=${encodeURIComponent(connectionId)}`), enabled: kind === 'categories' && !!connectionId && platform === 'TRENDYOL', retry: false })
  const mapping = useQuery({ queryKey: ['category-mapping', localId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${localId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: kind === 'categories' && !!localId && !!connectionId && platform === 'TRENDYOL', retry: false })
  const save = useMutation({ mutationFn: () => {
    if (!references.data || !localId || !externalId) throw new Error('Bağlantı, panel kategorisi ve Trendyol kategorisi zorunludur.')
    return hubApi<CatalogMapping>(`/mappings/categories/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) })
  }, onSuccess: async value => { setNotice('Kategori eşlemesi doğrulandı ve kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['category-mapping', localId, connectionId] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Eşleme kaydedilemedi.') })
  useEffect(() => { if (mapping.data) setExternalId(mapping.data.externalId) }, [mapping.data])
  const trendyolConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []
  const localLeaves = localCategories.data?.items.filter(item => item.isActive && item.isLeaf) ?? []
  const externalLeaves = references.data?.items.filter(item => item.isActive && item.isLeaf) ?? []
  const filteredLocalLeaves = localLeaves.filter(item => !localSearch.trim() || item.path.toLocaleLowerCase('tr-TR').includes(localSearch.trim().toLocaleLowerCase('tr-TR')))
  const filteredExternalLeaves = externalLeaves.filter(item => !externalSearch.trim() || item.path.toLocaleLowerCase('tr-TR').includes(externalSearch.trim().toLocaleLowerCase('tr-TR')))

  if (kind === 'categories' && new URLSearchParams(window.location.search).get('view') === 'brands') return <BrandMappingPage />
  if (kind === 'attributes') return <AttributeMappingPage />

  return <section className="content f3 mapping-page"><div className="page-heading"><div><p className="eyebrow">Merkezi katalog sistemi</p><h1>Kategori &amp; özellik eşlemeleri</h1><p className="lede">Panel kategorisini seçili pazaryerinin kategorisiyle eşleştirin; ardından kategori özellik başlıkları ve değer eşleştirmelerini aynı akışta tamamlayın.</p></div><Badge value="SAFE READ" /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <article className="panel mapping-step"><div className="editor-section-title"><span>1</span><div><h2>Panel kategorisini pazaryeri ile eşle</h2><p>Her pazaryeri için ayrı kategori eşleşmesi yapabilirsiniz.</p></div></div><div className="platform-choice"><strong>Pazaryeri:</strong>{['TRENDYOL', 'HEPSIBURADA', 'PAZARAMA', 'N11', 'SHOPIFY'].map(code => <button type="button" key={code} className={platform === code ? 'active' : ''} onClick={() => { setPlatform(code); setNotice('') }}>{code === 'TRENDYOL' ? 'Trendyol' : code === 'HEPSIBURADA' ? 'Hepsiburada' : code === 'PAZARAMA' ? 'Pazarama' : code}</button>)}</div>{platform !== 'TRENDYOL' ? <div className="unknown"><strong>Bu tasarım hazır</strong><p>Aktif fonksiyonel eşleme bu sürümde Trendyol için çalışır; diğer platform sekmeleri arayüz uyumunu korumak için gösterilir.</p></div> : <><div className="mapping-fields"><label>Aktif Trendyol bağlantısı<select aria-label="Aktif Trendyol bağlantısı" value={connectionId} onChange={event => { setConnectionId(event.target.value); setLocalId(''); setExternalId(''); setNotice('') }}><option value="">Bağlantı seçin</option>{trendyolConnections.map(item => <option value={item.id} key={item.id}>{item.displayName} · {item.externalStoreId}</option>)}</select></label><label>Panel yaprak kategorisi<input aria-label="Panel kategorilerinde ara" value={localSearch} onChange={event => setLocalSearch(event.target.value)} placeholder="Panel kategorilerinde ara" disabled={!connectionId} /><select aria-label="Panel yaprak kategorisi" value={localId} onChange={event => { setLocalId(event.target.value); setExternalId(''); setNotice('') }} disabled={!connectionId}><option value="">Kategori seçin</option>{filteredLocalLeaves.map(item => <option value={item.id} key={item.id}>{item.path}</option>)}</select></label><label>Trendyol yaprak kategorisi<input aria-label="Trendyol kategorilerinde ara" value={externalSearch} onChange={event => setExternalSearch(event.target.value)} placeholder="Trendyol kategorilerinde ara" disabled={!localId} /><select aria-label="Trendyol yaprak kategorisi" value={externalId} onChange={event => setExternalId(event.target.value)} disabled={!localId || references.isLoading || references.isError}><option value="">Kategori seçin</option>{filteredExternalLeaves.map(item => <option value={item.externalId} key={item.externalId}>{item.path}</option>)}</select></label></div>{connections.isError || localCategories.isError ? <ErrorBox error={connections.error ?? localCategories.error} /> : !trendyolConnections.length && !connections.isLoading ? <div className="mapping-action"><span>REFERENCE_READ kanıtlı ACTIVE Trendyol bağlantısı gerekir.</span><Link className="button-link" to="/integrations">Platformlara git</Link></div> : references.isError ? <div className="unknown"><strong>Güncel kategori snapshot’ı yok</strong><p>Bağlantı ekranından “Kategorileri eşitle” işlemini çalıştırın.</p><Link className="button-link" to={`/integrations/${connectionId}`}>Bağlantıya git</Link></div> : references.isLoading ? <Busy text="Kategori snapshot’ı yükleniyor…" /> : connectionId && references.data ? <div className="mapping-action"><span>{externalLeaves.length.toLocaleString('tr-TR')} yaprak kategori · snapshot {new Date(references.data.fetchedAt).toLocaleString('tr-TR')}{mapping.data ? ` · mevcut eşleme v${mapping.data.version}` : ''}</span><button type="button" disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşlemeyi güncelle' : 'Eşlemeyi doğrula ve kaydet'}</button></div> : null}</>}</article>

    <CategoryRequirementBuilder categoryId={localId} categoryVersion={currentCategory.data?.version ?? null} attributes={localAttributes.data?.items.filter(item => item.isActive) ?? []} requirements={requirements.data ?? []} onNotice={setNotice} onSaved={async () => { await client.invalidateQueries({ queryKey: ['category-requirements', localId, 'mapping'] }); await client.invalidateQueries({ queryKey: ['category', localId, 'mapping'] }); await client.invalidateQueries({ queryKey: ['attributes', 'mapping-builder'] }) }} />

    <CategoryAttributeWorkspace connectionId={connectionId} localCategoryId={localId} localAttributes={localAttributes.data?.items.filter(item => item.isActive) ?? []} categoryRequirements={requirements.data ?? []} onNotice={setNotice} />
  </section>
}

function slug(value: string) { return value.toLocaleLowerCase('tr-TR').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || `attr-${Date.now()}` }

function CategoryRequirementBuilder({ categoryId, categoryVersion, attributes, requirements, onNotice, onSaved }: { categoryId: string; categoryVersion: number | null; attributes: LocalAttribute[]; requirements: CategoryRequirementView[]; onNotice: (value: string) => void; onSaved: () => Promise<void> }) {
  const [selectedAttributeId, setSelectedAttributeId] = useState(''); const [title, setTitle] = useState(''); const [values, setValues] = useState(''); const [optionInputs, setOptionInputs] = useState<Record<string, string>>({})
  async function persist(next: Array<{ attributeId: string; isRequired: boolean; allowsCustomValue: boolean }>) {
    if (!categoryId || categoryVersion == null) return onNotice('Önce panel kategorisini seçin.')
    await hubApi(`/catalog/categories/${categoryId}/attribute-requirements`, { method: 'PUT', headers: { 'If-Match': `"v${categoryVersion}"` }, body: JSON.stringify(next.map((item, index) => ({ ...item, displayOrder: index }))) })
    await onSaved()
  }
  const current = requirements.map(item => ({ attributeId: item.attributeId, isRequired: item.isRequired, allowsCustomValue: item.allowsCustomValue }))
  async function addAttribute() {
    try {
      let attributeId = selectedAttributeId; let createdAttribute: LocalAttribute | null = null
      if (!attributeId && title.trim()) {
        const selectableValues = values.split(',').map(item => item.trim()).filter(Boolean)
        const payload = { code: slug(title), name: title.trim(), dataType: selectableValues.length ? 'SINGLE_SELECT' : 'TEXT', selectionMode: selectableValues.length ? 'SINGLE' : null, unit: null, values: selectableValues.map((value, index) => ({ value, sortOrder: index })) }
        createdAttribute = await hubApi<LocalAttribute>('/catalog/attributes', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(payload) })
        attributeId = createdAttribute.id
      }
      if (!attributeId) return onNotice('Yeni özellik başlığı girin veya mevcut bir özellik seçin.')
      if (requirements.some(item => item.attributeId === attributeId)) return onNotice('Bu özellik zaten kategoriye ekli.')
      let attribute = createdAttribute ?? attributes.find(item => item.id === attributeId) ?? null
      const requestedValues = values.split(',').map(item => item.trim()).filter(Boolean)
      if (!createdAttribute && requestedValues.length) attribute = await hubApi<LocalAttribute>(`/catalog/attributes/${attributeId}/values`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(requestedValues.map((value, sortOrder) => ({ value, sortOrder }))) })
      await persist([...current, { attributeId, isRequired: true, allowsCustomValue: !attribute?.values.length }])
      setSelectedAttributeId(''); setTitle(''); setValues(''); onNotice('Kategori özellik başlığı kaydedildi.')
    } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik kaydedilemedi.') }
  }
  async function removeAttribute(attributeId: string) { try { await persist(current.filter(item => item.attributeId !== attributeId)); onNotice('Özellik başlığı kaldırıldı.') } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik kaldırılamadı.') } }
  async function updateRequirement(attributeId: string, patch: Partial<{ isRequired: boolean; allowsCustomValue: boolean }>) {
    try { await persist(current.map(item => item.attributeId === attributeId ? { ...item, ...patch } : item)); onNotice('Kategori özellik kuralı güncellendi.') } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik kuralı güncellenemedi.') }
  }
  async function appendValues(attributeId: string) {
    const raw = optionInputs[attributeId] ?? ''; const items = raw.split(',').map(item => item.trim()).filter(Boolean)
    if (!items.length) return onNotice('Eklenecek seçenek değerlerini virgülle girin.')
    try {
      await hubApi<LocalAttribute>(`/catalog/attributes/${attributeId}/values`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(items.map((value, sortOrder) => ({ value, sortOrder }))) })
      setOptionInputs(currentValues => ({ ...currentValues, [attributeId]: '' })); await onSaved(); onNotice('Yeni seçenek değerleri eklendi.')
    } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Seçenek değerleri eklenemedi.') }
  }
  return <article className="panel mapping-step"><div className="editor-section-title"><span>2</span><div><h2>Ürün özellikleri</h2><p>Ürün aktarımında kullanacağınız özellik başlıklarını ve seçilebilir seçeneklerini bir kez oluşturun.</p></div></div>{!categoryId ? <div className="unknown"><strong>Önce kategori seçin</strong><p>Bu bölüm seçilen panel kategorisi için çalışır.</p></div> : <><div className="mapping-fields"><label>Yeni özellik başlığı<input value={title} onChange={event => setTitle(event.target.value)} placeholder="Örn. Kol Boyu, Paça Türü, Materyal" /></label><button type="button" onClick={addAttribute}>+ Özellik ekle</button><label>Mevcut özellik<select value={selectedAttributeId} onChange={event => setSelectedAttributeId(event.target.value)}><option value="">Özellik seçin</option>{attributes.filter(item => !requirements.some(req => req.attributeId === item.id)).map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Yeni seçenek değerleri<input value={values} onChange={event => setValues(event.target.value)} placeholder="Virgülle: Uzun kol, Kısa kol" /></label></div><div className="attribute-builder-list">{requirements.length ? requirements.map(item => <article className="attribute-summary-card" key={item.attributeId}><div><strong>{item.attribute.name}</strong><p>{item.attribute.values.length ? `${item.attribute.values.length} seçenek` : 'Serbest değer'}</p></div><div className="attribute-mini-values">{item.attribute.values.slice(0, 6).map(value => <span key={value.id}>{value.value}</span>)}</div>{['SINGLE_SELECT', 'MULTI_SELECT'].includes(item.attribute.dataType) && <div className="attribute-option-adder"><input value={optionInputs[item.attributeId] ?? ''} onChange={event => setOptionInputs(currentValues => ({ ...currentValues, [item.attributeId]: event.target.value }))} placeholder="Yeni seçenekleri virgülle girin" /><button type="button" className="secondary" onClick={() => appendValues(item.attributeId)}>+ Seçenek ekle</button></div>}<div className="requirement-controls"><label><input type="checkbox" checked={item.isRequired} onChange={event => void updateRequirement(item.attributeId, { isRequired: event.target.checked })} /> Zorunlu</label><label><input type="checkbox" checked={item.allowsCustomValue} onChange={event => void updateRequirement(item.attributeId, { allowsCustomValue: event.target.checked })} /> Özel değer</label><button type="button" className="secondary" onClick={() => removeAttribute(item.attributeId)}>Sil</button></div></article>) : <Empty>Kategoriye ait özellik başlığı henüz eklenmedi.</Empty>}</div></>}</article>
}

function CategoryAttributeWorkspace({ connectionId, localCategoryId, localAttributes, categoryRequirements, onNotice }: { connectionId: string; localCategoryId: string; localAttributes: LocalAttribute[]; categoryRequirements: CategoryRequirementView[]; onNotice: (value: string) => void }) {
  const categoryMapping = useQuery({ queryKey: ['category-mapping', localCategoryId, connectionId, 'embedded'], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${localCategoryId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!localCategoryId && !!connectionId, retry: false })
  const categoryScope = categoryMapping.data?.externalId ?? ''
  const references = useQuery({ queryKey: ['reference-attributes', connectionId, categoryScope, 'embedded'], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories/${encodeURIComponent(categoryScope)}/attributes?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId && !!categoryScope, retry: false })
  const mappings = useQuery({ queryKey: ['attribute-mappings', connectionId, categoryScope], queryFn: () => hubApi<CatalogMapping[]>(`/mappings/attributes?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(categoryScope)}`), enabled: !!connectionId && !!categoryScope, retry: false })
  const eligibleAttributes = localAttributes.filter(attribute => categoryRequirements.some(req => req.attributeId === attribute.id))
  const mappingByExternal = new Map((mappings.data ?? []).map(item => [item.externalId, item]))
  const usedLocalIds = new Set((mappings.data ?? []).map(item => item.localId))
  const remoteItems = references.data?.items.filter(item => item.isActive) ?? []
  const requiredItems = remoteItems.filter(item => item.isRequired)
  const mappedRequired = requiredItems.filter(item => mappingByExternal.has(item.externalId)).length
  if (!localCategoryId) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Sol taraftan merkezi ürün özelliğinizi seçin; ardından aynı karttan değer karşılıklarını eşleştirin.</p></div></div><div className="unknown"><strong>Kategori seçilmedi</strong><p>Önce panel kategorisini seçin.</p></div></article>
  if (!connectionId) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Sol taraftan merkezi ürün özelliğinizi seçin; ardından aynı karttan değer karşılıklarını eşleştirin.</p></div></div><div className="unknown"><strong>Bağlantı seçilmedi</strong><p>Önce aktif Trendyol bağlantısını seçin.</p></div></article>
  if (!categoryMapping.data) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Sol taraftan merkezi ürün özelliğinizi seçin; ardından aynı karttan değer karşılıklarını eşleştirin.</p></div></div><div className="unknown"><strong>Kategori eşlemesi bekleniyor</strong><p>Önce 1. adımda panel kategorisini Trendyol kategorisiyle eşleştirin.</p></div></article>
  return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Sol taraftan merkezi ürün özelliğinizi seçin; ardından aynı karttan değer karşılıklarını eşleştirin.</p></div></div>{references.isLoading || mappings.isLoading ? <Busy text="Kategori özellikleri ve eşlemeler yükleniyor…" /> : references.isError || mappings.isError ? <div className="unknown"><strong>Güncel kategori özellik verisi alınamadı</strong><p>Bağlantı detayından kategori özelliklerini eşitleyin ve tekrar deneyin.</p></div> : <><div className={`mapping-progress ${mappedRequired === requiredItems.length ? 'complete' : ''}`}><strong>{mappedRequired}/{requiredItems.length} zorunlu özellik eşlendi</strong><span>{remoteItems.length} toplam alan · {mappings.data?.length ?? 0} kayıtlı eşleme</span></div><div className="embedded-attribute-grid">{remoteItems.map(item => <CategoryAttributeCard key={item.externalId} connectionId={connectionId} categoryScope={categoryScope} snapshotId={references.data!.snapshotId} localAttributes={eligibleAttributes} remoteAttribute={item} existingMapping={mappingByExternal.get(item.externalId) ?? null} usedLocalIds={usedLocalIds} onNotice={onNotice} />)}</div></>}</article>
}

function CategoryAttributeCard({ connectionId, categoryScope, snapshotId, localAttributes, remoteAttribute, existingMapping, usedLocalIds, onNotice }: { connectionId: string; categoryScope: string; snapshotId: string; localAttributes: LocalAttribute[]; remoteAttribute: ReferenceItem; existingMapping: CatalogMapping | null; usedLocalIds: Set<string>; onNotice: (value: string) => void }) {
  const client = useQueryClient(); const [localId, setLocalId] = useState(existingMapping?.localId ?? ''); const [showValues, setShowValues] = useState(false)
  useEffect(() => { setLocalId(existingMapping?.localId ?? '') }, [existingMapping?.localId])
  const selectedAttribute = localAttributes.find(item => item.id === localId)
  const selectableAttributes = localAttributes.filter(item => item.id === localId || !usedLocalIds.has(item.id))
  async function save() {
    try {
      if (!localId) throw new Error('Entegrasyon ürün özelliğini seçin.')
      await hubApi<CatalogMapping>(`/mappings/attributes/${localId}`, { method: 'PUT', body: JSON.stringify({ connectionId, snapshotId, externalId: remoteAttribute.externalId, status: 'VERIFIED' }) })
      onNotice(`${remoteAttribute.name} eşlemesi kaydedildi.`)
      await client.invalidateQueries({ queryKey: ['attribute-mappings', connectionId, categoryScope] })
    } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik eşlemesi kaydedilemedi.') }
  }
  async function remove() {
    if (!existingMapping) return
    try {
      await hubApi<boolean>(`/mappings/attributes/${existingMapping.localId}?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(categoryScope)}`, { method: 'DELETE', headers: { 'If-Match': `"v${existingMapping.version}"` } })
      setShowValues(false); onNotice(`${remoteAttribute.name} eşlemesi kaldırıldı.`)
      await client.invalidateQueries({ queryKey: ['attribute-mappings', connectionId, categoryScope] })
    } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik eşlemesi kaldırılamadı.') }
  }
  const mapped = existingMapping?.externalId === remoteAttribute.externalId
  return <section className={`attribute-mapping-card ${remoteAttribute.isRequired ? 'required' : ''} ${remoteAttribute.isRequired && !mapped ? 'unmapped' : ''}`}><div className="attribute-mapping-card-head"><span className="attr-source">TY</span><div><strong>{remoteAttribute.name}</strong><small>{remoteAttribute.isRequired ? 'Zorunlu' : 'İsteğe bağlı'}{mapped ? ' · eşlendi' : ''}</small></div></div><div className="mapping-fields compact"><label>Entegrasyon ürün özelliği<select value={localId} onChange={event => setLocalId(event.target.value)} disabled={mapped}><option value="">Özellik seçin</option>{selectableAttributes.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{mapped ? <button type="button" className="secondary" onClick={() => void remove()}>Eşlemeyi kaldır</button> : <button type="button" onClick={() => void save()} disabled={!localId}>Kaydet</button>}</div>{selectedAttribute && mapped && selectedAttribute.values.length > 0 && <><button type="button" className="value-mapping-toggle" onClick={() => setShowValues(value => !value)}>{showValues ? 'Değer eşlemelerini gizle' : `Değer eşlemelerini aç (${selectedAttribute.values.length})`}</button>{showValues && <AttributeValueMappingEditor connectionId={connectionId} categoryScope={categoryScope} attribute={selectedAttribute} externalAttributeId={remoteAttribute.externalId} />}</>}</section>
}

export function AttributeMappingPage() {
  const client = useQueryClient(); const [connectionId, setConnectionId] = useState(''); const [categoryId, setCategoryId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'attribute-mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const categories = useQuery({ queryKey: ['categories', 'attribute-mapping'], queryFn: () => hubApi<Page<LocalCategory>>('/catalog/categories?limit=200') })
  const localAttributes = useQuery({ queryKey: ['attributes', 'mapping'], queryFn: () => hubApi<Page<LocalAttribute>>('/catalog/attributes?limit=200') })
  const categoryMapping = useQuery({ queryKey: ['category-mapping', categoryId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${categoryId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!categoryId && !!connectionId, retry: false })
  const categoryScope = categoryMapping.data?.externalId ?? ''
  const references = useQuery({ queryKey: ['reference-attributes', connectionId, categoryScope], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories/${encodeURIComponent(categoryScope)}/attributes?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId && !!categoryScope, retry: false })
  const mapping = useQuery({ queryKey: ['attribute-mapping', localId, connectionId, categoryScope], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/attributes/${localId}?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(categoryScope)}`), enabled: !!localId && !!connectionId && !!categoryScope, retry: false })
  const sync = useMutation({ mutationFn: () => hubApi(`/connections/${connectionId}/reference-sync-jobs?resourceType=CATEGORY_ATTRIBUTES&parentExternalId=${encodeURIComponent(categoryScope)}`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: '{}' }), onSuccess: () => setNotice('Kategori özellikleri salt-okunur eşitleme kuyruğuna alındı.'), onError: reason => setNotice(reason instanceof Error ? reason.message : 'Özellik eşitleme başlatılamadı.') })
  const save = useMutation({ mutationFn: () => {
    if (!references.data || !localId || !externalId) throw new Error('Bağlantı, kategori, panel özelliği ve Trendyol özelliği zorunludur.')
    return hubApi<CatalogMapping>(`/mappings/attributes/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) })
  }, onSuccess: async value => { setNotice('Özellik eşlemesi doğrulandı ve kategori kapsamında kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['attribute-mapping', localId, connectionId, categoryScope] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Özellik eşlemesi kaydedilemedi.') })
  useEffect(() => { if (mapping.data) setExternalId(mapping.data.externalId) }, [mapping.data])
  const activeConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []; const localLeaves = categories.data?.items.filter(item => item.isActive && item.isLeaf) ?? []; const activeAttributes = localAttributes.data?.items.filter(item => item.isActive) ?? []; const remoteAttributes = references.data?.items.filter(item => item.isActive) ?? []
  return <section className="content f3 mapping-page"><div className="page-heading"><div><p className="eyebrow">Eşleştirme ayarları</p><h1>Özellik eşlemeleri</h1><p className="lede">Yerel özellikleri güncel Trendyol V2 kategori özelliği snapshot’ına kategori kapsamında eşleyin.</p></div><Badge value="SAFE READ" /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="button-row"><Link className="button-link secondary" to="/mappings/categories">Kategoriler</Link><Link className="button-link secondary" to="/mappings/categories?view=brands">Markalar</Link><Link className="button-link" to="/mappings/attributes">Özellikler</Link></div>
    <article className="panel mapping-step"><div className="editor-section-title"><span>1</span><div><h2>Kategori kapsamını seçin</h2><p>Özellik kimlikleri seçili ve doğrulanmış Trendyol yaprak kategorisi kapsamında tutulur.</p></div></div><div className="mapping-fields"><label>Özellik için aktif Trendyol bağlantısı<select aria-label="Özellik için aktif Trendyol bağlantısı" value={connectionId} onChange={event => { setConnectionId(event.target.value); setCategoryId(''); setLocalId(''); setExternalId(''); setNotice('') }}><option value="">Bağlantı seçin</option>{activeConnections.map(item => <option value={item.id} key={item.id}>{item.displayName} · {item.externalStoreId}</option>)}</select></label><label>Panel yaprak kategorisi<select aria-label="Özellik kapsamı panel kategorisi" value={categoryId} onChange={event => { setCategoryId(event.target.value); setLocalId(''); setExternalId(''); setNotice('') }} disabled={!connectionId}><option value="">Kategori seçin</option>{localLeaves.map(item => <option value={item.id} key={item.id}>{item.path}</option>)}</select></label></div>
      {categoryId && !categoryMapping.isLoading && !categoryMapping.data ? <div className="unknown"><strong>Kategori eşlemesi gerekli</strong><p>Özellikleri almadan önce panel kategorisini Trendyol yaprak kategorisiyle eşleyin.</p><Link className="button-link" to="/mappings/categories">Kategori eşlemelerine git</Link></div> : categoryScope && references.isError ? <div className="unknown"><strong>Güncel özellik snapshot’ı yok</strong><p>Seçili kategori için yalnız salt-okunur özellik listesini eşitleyin.</p><button disabled={sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Kuyruğa alınıyor…' : 'Kategori özelliklerini eşitle'}</button></div> : null}</article>
    {references.data && <article className="panel mapping-step"><div className="editor-section-title"><span>2</span><div><h2>Özelliği eşleyin</h2><p>Bu işlem yalnız yerel mapping kaydı oluşturur; Trendyol’a yazmaz.</p></div></div><div className="mapping-fields"><label>Panel özelliği<select aria-label="Panel özelliği" value={localId} onChange={event => { setLocalId(event.target.value); setExternalId(''); setNotice('') }}><option value="">Özellik seçin</option>{activeAttributes.map(item => <option value={item.id} key={item.id}>{item.name} · {item.dataType}</option>)}</select></label><label>Trendyol kategori özelliği<select aria-label="Trendyol kategori özelliği" value={externalId} onChange={event => setExternalId(event.target.value)} disabled={!localId || mapping.isLoading}><option value="">Özellik seçin</option>{remoteAttributes.map(item => <option value={item.externalId} key={item.externalId}>{item.name}{item.isRequired ? ' · zorunlu' : ''}{item.allowsCustomValue ? ' · serbest değer' : ''}</option>)}</select></label></div><div className="mapping-action"><span>{remoteAttributes.length.toLocaleString('tr-TR')} özellik · kategori {categoryScope}{mapping.data ? ` · mevcut eşleme v${mapping.data.version}` : ''}</span><button disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşlemeyi güncelle' : 'Eşlemeyi doğrula ve kaydet'}</button></div>{mapping.data && localId && <AttributeValueMappingEditor connectionId={connectionId} categoryScope={categoryScope} attribute={activeAttributes.find(item => item.id === localId)!} externalAttributeId={mapping.data.externalId} />}</article>}
  </section>
}

function AttributeValueMappingEditor({ connectionId, categoryScope, attribute, externalAttributeId }: { connectionId: string; categoryScope: string; attribute: LocalAttribute; externalAttributeId: string }) {
  const client = useQueryClient(); const [notice, setNotice] = useState(''); const [selections, setSelections] = useState<Record<string, string>>({}); const [saving, setSaving] = useState(false); const valueScope = `${categoryScope}/${externalAttributeId}`
  const references = useQuery({ queryKey: ['reference-attribute-values', connectionId, valueScope], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories/${encodeURIComponent(categoryScope)}/attributes/${encodeURIComponent(externalAttributeId)}/values?connectionId=${encodeURIComponent(connectionId)}`), retry: false })
  const mappings = useQuery({ queryKey: ['attribute-value-mappings', connectionId, valueScope], queryFn: () => hubApi<CatalogMapping[]>(`/mappings/attribute-values?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(valueScope)}`), retry: false })
  const sync = useMutation({ mutationFn: () => hubApi(`/connections/${connectionId}/reference-sync-jobs?resourceType=ATTRIBUTE_VALUES&parentExternalId=${encodeURIComponent(valueScope)}`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: '{}' }), onSuccess: () => setNotice('Özellik değerleri salt-okunur eşitleme kuyruğuna alındı.'), onError: reason => setNotice(reason instanceof Error ? reason.message : 'Değer eşitleme başlatılamadı.') })
  const localValues = attribute.values?.filter(item => item.isActive) ?? []; const remoteValues = references.data?.items.filter(item => item.isActive) ?? []; const mappingByLocal = new Map((mappings.data ?? []).map(item => [item.localId, item]))
  useEffect(() => { if (mappings.data) setSelections(Object.fromEntries(mappings.data.map(item => [item.localId, item.externalId]))) }, [mappings.data])
  async function saveAll() {
    if (!references.data) return
    const chosen = Object.values(selections).filter(Boolean)
    if (new Set(chosen).size !== chosen.length) return setNotice('Aynı Trendyol değeri birden fazla panel değerine eşlenemez.')
    setSaving(true); setNotice('')
    try {
      var changed = 0
      for (const localValue of localValues) {
        const externalId = selections[localValue.id] ?? ''
        const existing = mappingByLocal.get(localValue.id)
        if (!externalId && existing) {
          await hubApi<boolean>(`/mappings/attribute-values/${localValue.id}?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(valueScope)}`, { method: 'DELETE', headers: { 'If-Match': `"v${existing.version}"` } })
          changed++
          continue
        }
        if (!externalId || existing?.externalId === externalId) continue
        await hubApi<CatalogMapping>(`/mappings/attribute-values/${localValue.id}`, { method: 'PUT', headers: existing ? { 'If-Match': `"v${existing.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) })
        changed++
      }
      await client.invalidateQueries({ queryKey: ['attribute-value-mappings', connectionId, valueScope] })
      setNotice(changed ? `${changed} değer eşlemesi kaydedildi.` : 'Değer eşlemelerinde değişiklik yok.')
    } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Değer eşlemeleri kaydedilemedi.') } finally { setSaving(false) }
  }
  if (!localValues.length) return <div className="unknown"><strong>Serbest değer özelliği</strong><p>Bu yerel özellik seçim listesi taşımıyor; Trendyol özelliği serbest değer kabul etmiyorsa yayınlama kapısı işlemi reddeder.</p></div>
  if (references.isError) return <div className="unknown"><strong>Güncel özellik değerleri snapshot’ı yok</strong><p>Seçili kategori ve özellik için salt-okunur değer listesini eşitleyin.</p>{notice && <p role="status">{notice}</p>}<button disabled={sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Kuyruğa alınıyor…' : 'Özellik değerlerini eşitle'}</button></div>
  if (references.isLoading || mappings.isLoading) return <Busy text="Özellik değerleri ve mevcut eşlemeler yükleniyor…" />
  if (mappings.isError) return <ErrorBox error={mappings.error} />
  const used = new Set(Object.values(selections).filter(Boolean))
  return <div className="mapping-step nested value-mapping-editor"><div className="value-mapping-heading"><div><h3>Değer eşleştirmeleri</h3><p>{localValues.length} panel değeri · {remoteValues.length} Trendyol değeri</p></div><button type="button" disabled={saving} onClick={() => void saveAll()}>{saving ? 'Kaydediliyor…' : 'Tüm eşlemeleri kaydet'}</button></div>{notice && <p role="status" className="notice">{notice}</p>}<div className="value-mapping-rows">{localValues.map(localValue => <label key={localValue.id} className="value-mapping-row"><span>{localValue.value}</span><b>→</b><select aria-label={`${localValue.value} Trendyol değeri`} value={selections[localValue.id] ?? ''} onChange={event => setSelections(current => ({ ...current, [localValue.id]: event.target.value }))}><option value="">Trendyol değeri seçin</option>{remoteValues.map(remote => <option key={remote.externalId} value={remote.externalId} disabled={used.has(remote.externalId) && selections[localValue.id] !== remote.externalId}>{remote.name}</option>)}</select><small>{mappingByLocal.has(localValue.id) ? 'Eşlendi' : 'Bekliyor'}</small></label>)}</div></div>
}

export function BrandMappingPage() {
  const client = useQueryClient(); const [connectionId, setConnectionId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'brand-mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const localBrands = useQuery({ queryKey: ['brands', 'mapping'], queryFn: () => hubApi<Page<LocalBrand>>('/catalog/brands?limit=200') })
  const references = useQuery({ queryKey: ['reference-brands', connectionId], queryFn: () => hubApi<ReferenceData>(`/reference-data/brands?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId, retry: false })
  const mapping = useQuery({ queryKey: ['brand-mapping', localId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/brands/${localId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!localId && !!connectionId, retry: false })
  const save = useMutation({ mutationFn: () => {
    if (!references.data || !localId || !externalId) throw new Error('Bağlantı, panel markası ve Trendyol markası zorunludur.')
    return hubApi<CatalogMapping>(`/mappings/brands/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) })
  }, onSuccess: async value => { setNotice('Marka eşlemesi doğrulandı ve kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['brand-mapping', localId, connectionId] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Eşleme kaydedilemedi.') })
  useEffect(() => { setExternalId(mapping.data?.externalId ?? '') }, [mapping.data])
  const trendyolConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []
  const activeLocalBrands = localBrands.data?.items.filter(item => item.isActive) ?? []
  const externalBrands = references.data?.items.filter(item => item.isActive) ?? []

  return <section className="content f3 mapping-page"><div className="page-heading"><div><p className="eyebrow">Eşleştirme ayarları</p><h1>Marka eşlemeleri</h1><p className="lede">Yerel markayı doğrulanmış Trendyol marka snapshot’ındaki kimlikle eşleştirin.</p></div><Badge value="SAFE READ" /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="button-row"><Link className="button-link secondary" to="/mappings/categories">Kategoriler</Link><Link className="button-link" to="/mappings/categories?view=brands">Markalar</Link><Link className="button-link secondary" to="/mappings/attributes">Özellikler</Link></div>
    <article className="panel mapping-step"><div className="editor-section-title"><span>1</span><div><h2>Trendyol marka eşlemesi</h2><p>Bu işlem yalnız yerel mapping kaydı oluşturur; Trendyol’a veri göndermez.</p></div></div>
      <div className="mapping-fields"><label>Aktif Trendyol bağlantısı<select aria-label="Marka için aktif Trendyol bağlantısı" value={connectionId} onChange={event => { setConnectionId(event.target.value); setLocalId(''); setExternalId(''); setNotice('') }}><option value="">Bağlantı seçin</option>{trendyolConnections.map(item => <option value={item.id} key={item.id}>{item.displayName} · {item.externalStoreId}</option>)}</select></label>
        <label>Panel markası<select aria-label="Panel markası" value={localId} onChange={event => { setLocalId(event.target.value); setExternalId(''); setNotice('') }} disabled={!connectionId}><option value="">Marka seçin</option>{activeLocalBrands.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>
        <label>Trendyol markası<select aria-label="Trendyol markası" value={externalId} onChange={event => setExternalId(event.target.value)} disabled={!localId || references.isLoading || references.isError}><option value="">Marka seçin</option>{externalBrands.map(item => <option value={item.externalId} key={item.externalId}>{item.name}</option>)}</select></label></div>
      {connections.isError || localBrands.isError ? <ErrorBox error={connections.error ?? localBrands.error} /> : references.isError ? <div className="unknown"><strong>Güncel marka snapshot’ı yok</strong><p>Bağlantı ekranından “Markaları eşitle” işlemini çalıştırın.</p><Link className="button-link" to={`/integrations/${connectionId}`}>Bağlantıya git</Link></div> : references.isLoading ? <Busy text="Marka snapshot’ı yükleniyor…" /> : connectionId && references.data ? <div className="mapping-action"><span>{externalBrands.length.toLocaleString('tr-TR')} marka · snapshot {new Date(references.data.fetchedAt).toLocaleString('tr-TR')}{mapping.data ? ` · mevcut eşleme v${mapping.data.version}` : ''}</span><button type="button" disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşlemeyi güncelle' : 'Eşlemeyi doğrula ve kaydet'}</button></div> : null}
    </article></section>
}

function ListPage({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children: React.ReactNode }) { return <section className="content f3"><div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="lede">{description}</p></div><Badge value="LIVE READ" /></div><div className="panel">{children}</div></section> }
